def format_size(size_bytes):
    if size_bytes < 1024:        return f"{size_bytes} B"
    elif size_bytes < 1024**2:   return f"{size_bytes/1024:.1f} KB"
    elif size_bytes < 1024**3:   return f"{size_bytes/(1024**2):.1f} MB"
    else:                        return f"{size_bytes/(1024**3):.2f} GB"

# ══════════════════════════════════════════════════════════════════════════════
# Per-scan read caches (v0.18.3)                                 ### NEW v0.18.3 ###
# ══════════════════════════════════════════════════════════════════════════════
# A movie's NFO and XML used to be opened and parsed ~10 times per scan (name,
# year, genres, rating, votes, IDs, titles, language, validation…) and each
# image header 3 times.  These caches key on (mtime_ns, size) so a file edited
# by the app (or by the user) is re-read automatically.  Bounded; cleared at
# the start of every scan by clear_read_caches().
_TEXT_CACHE   = {}
_ROOT_CACHE   = {}
_IMG_WH_CACHE = {}
_NOT_UTF8_CACHE = {}                                            ### NEW v0.19.2 B37 — (path, stat key) → info note ###
_CACHE_MAX    = 6000
_AMP_FIX_RE   = re.compile(r'&(?!amp;|lt;|gt;|quot;|apos;|#)')


def _stat_key(path):
    try:
        st = os.stat(path)
        return (st.st_mtime_ns, st.st_size)
    except OSError:
        return None


def _cache_put(cache, key, value):
    if len(cache) >= _CACHE_MAX:
        cache.clear()
    cache[key] = value


def _read_text(path):
    """Return the file's text (BOM stripped) or None if unreadable."""
    if not path:
        return None
    sk = _stat_key(path)
    if sk is None:
        return None
    key = (path, sk)
    hit = _TEXT_CACHE.get(key)
    if hit is not None:
        return hit
    try:
        with open(path, "rb") as f:                            ### MODIFIED v0.19.2 B37 \u2014 bytes, strict UTF-8 first ###
            raw = f.read()
    except Exception:
        return None
    try:
        content = raw.decode("utf-8")
    except UnicodeDecodeError as ex:                           ### NEW v0.19.2 B37 \u2014 remember the first bad byte ###
        content = raw.decode("utf-8", errors="replace")
        _cache_put(_NOT_UTF8_CACHE, key, {
            "line": raw.count(b"\n", 0, ex.start) + 1,
            "col": ex.start - (raw.rfind(b"\n", 0, ex.start) + 1) + 1,
            "message": f"Not UTF-8 (byte 0x{raw[ex.start]:02X}) \u2014 MediaClinic will not change this "
                       f"file; convert it to UTF-8 first"})
    content = content.replace("\r\n", "\n").replace("\r", "\n")   # as the text-mode read did
    if content.startswith("\ufeff"):
        content = content[1:]
    _cache_put(_TEXT_CACHE, key, content)
    return content


def _not_utf8_note(path):                                      ### NEW v0.19.2 B37 ###
    """Info note {line, col, message} when *path* is not valid UTF-8, else None."""
    sk = _stat_key(path) if path else None
    if sk is None or _read_text(path) is None:
        return None
    return _NOT_UTF8_CACHE.get((path, sk))


def _parse_root(path):
    """Return the parsed ElementTree root (with KODI-safe & handling) or None."""
    if not path:
        return None
    sk = _stat_key(path)
    if sk is None:
        return None
    key = (path, sk)
    if key in _ROOT_CACHE:
        return _ROOT_CACHE[key]
    content = _read_text(path)
    root = None
    if content is not None:
        try:
            root = ET.fromstring(_AMP_FIX_RE.sub("&amp;", content))
        except Exception:
            root = None
    _cache_put(_ROOT_CACHE, key, root)
    return root


def clear_read_caches():
    _TEXT_CACHE.clear(); _ROOT_CACHE.clear(); _IMG_WH_CACHE.clear()
    _IMG_PROBE_CACHE.clear()                                    ### NEW v0.19.0 ###
    _NOT_UTF8_CACHE.clear()                                     ### NEW v0.19.2 B37 ###


_IMG_PROBE_CACHE = {}                                           ### NEW v0.19.0 ###


def get_jpeg_dimensions(filepath):
    """Parse JPEG dimensions from SOF marker.
    v0.11.1: added max-segment guard to prevent infinite loop on corrupt files.
    """                                                      ### NEW v0.11.1 ###
    try:
        with open(filepath, "rb") as f:
            if f.read(2) != b'\xff\xd8': return None, None
            _MAX_SEGMENTS = 2000   # safety guard — no valid JPEG has more ### NEW v0.11.1 ###
            for _ in range(_MAX_SEGMENTS):
                marker = f.read(2)
                if len(marker) < 2 or marker[0] != 0xFF: return None, None
                m = marker[1]
                # Skip fill bytes (0xFF padding)
                _fill_guard = 0
                while m == 0xFF:
                    b = f.read(1)
                    if len(b) < 1: return None, None
                    m = b[0]
                    _fill_guard += 1
                    if _fill_guard > 16: return None, None   # malformed padding ### NEW v0.11.1 ###
                if m in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
                    f.read(3); hw = f.read(4)
                    if len(hw) < 4: return None, None
                    return struct.unpack(">H", hw[2:4])[0], struct.unpack(">H", hw[0:2])[0]
                elif m in (0xD9, 0xDA):
                    return None, None   # EOI / SOS — no SOF found
                else:
                    d = f.read(2)
                    if len(d) < 2: return None, None
                    seg_len = struct.unpack(">H", d)[0]
                    if seg_len < 2: return None, None   # prevent seek(0,1) loop ### NEW v0.11.1 ###
                    f.seek(seg_len - 2, 1)
            return None, None   # exceeded segment limit
    except Exception: return None, None

def get_png_dimensions(filepath):
    try:
        with open(filepath, "rb") as f:
            if f.read(8)[:4] != b'\x89PNG': return None, None
            f.read(4)
            if f.read(4) != b'IHDR': return None, None
            d = f.read(8)
            if len(d) < 8: return None, None
            return struct.unpack(">I", d[0:4])[0], struct.unpack(">I", d[4:8])[0]
    except Exception: return None, None

### MODIFIED v0.19.0 — the format is detected from the file signature, not the
### extension (a PNG named poster.jpg used to return no dimensions) ###
_EXT_FORMAT = {".jpg": "JPEG", ".jpeg": "JPEG", ".jpe": "JPEG", ".png": "PNG",
               ".gif": "GIF", ".bmp": "BMP", ".webp": "WEBP"}


def detect_image_format(filepath):                             ### NEW v0.19.0 ###
    """Image format from the file signature: 'JPEG', 'PNG', 'GIF', 'BMP',
    'WEBP' or None (unknown / unreadable / empty)."""
    try:
        with open(filepath, "rb") as f:
            head = f.read(12)
    except Exception:
        return None
    if head[:3] == b"\xff\xd8\xff":
        return "JPEG"
    if head[:8] == b"\x89PNG\r\n\x1a\n":
        return "PNG"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return "GIF"
    if head[:2] == b"BM":
        return "BMP"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "WEBP"
    return None


def _file_tail_has(filepath, marker, n=64):                    ### NEW v0.19.0 ###
    """True when *marker* occurs in the last *n* bytes of the file (JPEG EOI,
    PNG IEND).  Trailing padding after the marker is tolerated."""
    try:
        with open(filepath, "rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - n))
            return marker in f.read(n)
    except Exception:
        return False


def _pil_decode(filepath):                                     ### NEW v0.19.0 ###
    """Full decode with Pillow.  Returns (ok, w, h); ok is None when Pillow
    is not installed."""
    if not _PIL_AVAILABLE:
        return None, None, None
    try:
        with _PILImage.open(filepath) as im:
            w, h = im.size
            im.load()
        return True, w, h
    except Exception:
        return False, None, None


def probe_image(filepath):                                     ### NEW v0.19.0 ###
    """
    Read the facts about one image file (I/O; cached per path + mtime + size):
      exists, bytes, format (from the signature), ext_format (from the name),
      w, h, decode_ok, mismatch.
    decode_ok is True when the header parses AND the file ends with its end
    marker; a failed fast check is confirmed with a full Pillow decode when
    Pillow is installed, so trailing bytes never produce a false "corrupt".
    Without Pillow the fast check decides.  No settings are read here —
    evaluate_image() turns these facts into a status.
    """
    empty = {"exists": False, "bytes": 0, "format": None, "ext_format": None,
             "w": None, "h": None, "decode_ok": None, "mismatch": False}
    if not filepath:
        return dict(empty)
    sk = _stat_key(filepath)
    if sk is None or not os.path.isfile(filepath):
        return dict(empty)
    key = (filepath, sk)
    hit = _IMG_PROBE_CACHE.get(key)
    if hit is not None:
        return dict(hit)
    size = sk[1]
    fmt = detect_image_format(filepath) if size > 0 else None
    ext_fmt = _EXT_FORMAT.get(os.path.splitext(filepath)[1].lower())
    w = h = None
    ok = False
    if fmt == "JPEG":
        w, h = get_jpeg_dimensions(filepath)
        ok = bool(w and h) and _file_tail_has(filepath, b"\xff\xd9")
    elif fmt == "PNG":
        w, h = get_png_dimensions(filepath)
        ok = bool(w and h) and _file_tail_has(filepath, b"IEND")
    elif fmt is not None:
        pil_ok, w, h = _pil_decode(filepath)
        ok = True if pil_ok is None else pil_ok
    if not ok and fmt is not None and _PIL_AVAILABLE:
        pil_ok, pw, ph = _pil_decode(filepath)           # confirm before calling it corrupt
        if pil_ok:
            ok = True
            if not (w and h):
                w, h = pw, ph
    pr = {"exists": True, "bytes": size, "format": fmt, "ext_format": ext_fmt,
          "w": w if ok else w, "h": h if ok else h, "decode_ok": bool(ok),
          "mismatch": bool(fmt and ext_fmt and fmt != ext_fmt)}
    _cache_put(_IMG_PROBE_CACHE, key, pr)
    return dict(pr)


def get_image_wh(filepath):
    """Return (width, height) integers or (None, None).  Cached per file
    (mtime + size) so the header is parsed once per scan.
    ### MODIFIED v0.19.0 — signature-based, via probe_image ###"""
    if not filepath:
        return None, None
    sk = _stat_key(filepath)
    if sk is None:
        return None, None
    key = (filepath, sk)
    hit = _IMG_WH_CACHE.get(key)
    if hit is not None:
        return hit
    pr = probe_image(filepath)
    wh = (pr["w"], pr["h"]) if (pr["w"] and pr["h"]) else (None, None)
    _cache_put(_IMG_WH_CACHE, key, wh)
    return wh

def get_image_dimensions(filepath):
    w, h = get_image_wh(filepath)
    return f"{w}×{h}" if w and h else None

def _parse_dim_str(dim_str):                                   ### NEW v0.19.0 — module level ###
    """'1920×1080' (or 1920x1080) → (1920, 1080); (None, None) otherwise."""
    if not dim_str:
        return None, None
    try:
        for sep in ('×', 'x', 'X'):
            if sep in dim_str:
                parts = dim_str.split(sep)
                return int(parts[0]), int(parts[1])
    except (ValueError, IndexError):
        pass
    return None, None

def is_valid_jpeg(filepath):
    """Kept for compatibility: True when the file is a decodable JPEG.
    ### MODIFIED v0.19.0 — uses probe_image (signature + EOI + Pillow) ###"""
    pr = probe_image(filepath)
    return bool(pr["exists"] and pr["format"] == "JPEG" and pr["decode_ok"])

def classify_quality(width, height):
    if width is None or height is None:
        return "—"
    if not width or not height:
        return "—"
    long_side  = max(width, height)
    short_side = min(width, height)
    # For HD: use long_side (width) — 1920x1040 long=1920 → 1080p ✓
    # For SD: use short_side (height in landscape) — 720x576 short=576 → 576p ✓
    if long_side  >= 3840: return "4K UHD"
    if long_side  >= 2560: return "1440p"
    if long_side  >= 1920: return "1080p"
    if long_side  >= 1280: return "720p"
    if short_side >= 576:  return "576p/DVD"
    if short_side >= 480:  return "480p"
    if short_side >= 360:  return "360p"
    if short_side >= 240:  return "240p"
    return "SD"

def _quality_sort_key(label):
    order = {"4K UHD":0,"1440p":1,"1080p":2,"720p":3,
             "576p/DVD":4,"480p":5,"360p":6,"240p":7,"SD":8,"—":9}
    return order.get(label, 9)


# ── Image health check ────────────────────────────────────────────────────────
### REWRITTEN v0.19.0 — one pure evaluation (evaluate_image) over the facts
### read by probe_image().  Only a real decode failure is "corrupt" (✕); size,
### resolution, proportion and format problems are separate warnings (◐) whose
### health severity follows the Health Rules.  The minimum quality has ONE
### source: the Health Rules keys (_min_quality_level). ###

_IMAGE_LABELS = {"poster": "Poster", "folder": "Folder", "fanart": "Fanart"}
_IMAGE_FILES  = {"poster": "poster.jpg", "folder": "folder.jpg", "fanart": "fanart.jpg"}


def _min_quality_level(image_type, settings=None):            ### NEW v0.19.0 ###
    """The ONE authoritative minimum quality tier for an image type: the
    Health Rules keys.  (poster_quality_level / folder_quality_level /
    fanart_quality_level in Image Sizes are mirrors written on save.)"""
    s = settings if settings is not None else SETTINGS
    rules = s.get("health_rules") or {}
    if image_type == "fanart":
        return rules.get("fanart_quality_level_minimum") or "1080p"
    return rules.get("poster_folder_quality_level") or "1080p"


def evaluate_image(probe, image_type, settings=None):         ### NEW v0.19.0 ###
    """
    Pure: (status, description, flags) for one artwork file from the facts in
    *probe* (see probe_image) and the current settings.  No I/O.
      flags = {"corrupt", "too_small", "low_res", "bad_ratio", "mismatch"}
    Status: ○ missing, ✕ corrupt (cannot be decoded), ◐ any other flag, ⬤ ok.
    """
    s = settings if settings is not None else SETTINGS
    flags = {"corrupt": False, "too_small": False, "low_res": False,
             "bad_ratio": False, "mismatch": False}
    if not probe or not probe.get("exists"):
        return STATUS_MISSING, "File missing", flags
    reasons = []
    size_bytes = probe.get("bytes") or 0
    w, h = probe.get("w"), probe.get("h")
    if size_bytes == 0:
        flags["corrupt"] = True
        reasons.append("File is empty (0 bytes)")
    elif probe.get("format") is None:
        flags["corrupt"] = True
        reasons.append("Not a recognised image file (no JPEG/PNG signature)")
    elif probe.get("decode_ok") is False:
        flags["corrupt"] = True
        reasons.append(f"{probe.get('format')} data cannot be decoded (truncated or damaged file)")

    # ── minimum file size (KB) — Image Sizes tab, 0 = skip ──────────────────
    min_kb = s.get(f"min_{image_type}_kb", 200 if image_type == "fanart" else 100) or 0
    if size_bytes > 0 and min_kb > 0 and size_bytes < min_kb * 1024:
        flags["too_small"] = True
        reasons.append(f"File size {size_bytes // 1024} KB is below the {min_kb} KB minimum")

    if w and h:
        # ── minimum resolution tier — Health Rules (single source) ───────────
        min_level = _min_quality_level(image_type, s)
        label = classify_image_quality(w, h, image_type)
        sort_key = _fanart_quality_sort_key if image_type == "fanart" else _poster_quality_sort_key
        if label not in ("—", None, "") and sort_key(label) > sort_key(min_level):
            flags["low_res"] = True
            reasons.append(f"Resolution {w}×{h} ({label}) is below the minimum quality '{min_level}'")
        # ── proportions ───────────────────────────────────────────────────────
        ratio = w / h
        if image_type in ("poster", "folder"):
            ok_23 = (0.60 <= ratio <= 0.72); ok_34 = (0.70 <= ratio <= 0.80)
            if s.get("poster_accept_34", False):
                if not (ok_23 or ok_34):
                    flags["bad_ratio"] = True
                    reasons.append(f"Proportions {w}×{h} ({ratio:.2f}) — expected 2:3 (≈0.67) or 3:4 (≈0.75)")
            elif not ok_23:
                flags["bad_ratio"] = True
                reasons.append(f"Proportions {w}×{h} ({ratio:.2f}) — expected 2:3 portrait (≈0.67)")
        else:
            ok_169 = (1.70 <= ratio <= 1.85); ok_168 = (1.45 <= ratio <= 1.55)
            if s.get("fanart_accept_168", False):
                if not (ok_169 or ok_168):
                    flags["bad_ratio"] = True
                    reasons.append(f"Proportions {w}×{h} ({ratio:.2f}) — expected 16:9 (≈1.78) or 16:8 (≈1.50)")
            elif not ok_169:
                flags["bad_ratio"] = True
                reasons.append(f"Proportions {w}×{h} ({ratio:.2f}) — expected 16:9 landscape (≈1.78)")

    if probe.get("mismatch"):
        flags["mismatch"] = True
        reasons.append(f"{_IMAGE_FILES.get(image_type, 'file')} is a {probe.get('format')} file (extension mismatch)")

    if flags["corrupt"]:
        status = STATUS_ERROR
    elif any(flags.values()):
        status = STATUS_WARN
    else:
        status = STATUS_OK
    return status, "; ".join(reasons), flags


def check_image_health(filepath, image_type):
    """(status, description) for one artwork file.  ### REWRITTEN v0.19.0 —
    thin wrapper over probe_image + evaluate_image; STATUS_ERROR now means
    'cannot be decoded' only ###"""
    st, desc, _flags = evaluate_image(probe_image(filepath), image_type)
    return st, desc


def _image_row_fields(key, image_type, path, exists):          ### NEW v0.19.0 ###
    """All row fields for one artwork file (poster/folder/fanart), used by
    scan_one_subfolder and the parallel image phase."""
    pr = probe_image(path) if exists else None
    if not pr or not pr["exists"]:
        return {f"{key}_exists": False, f"{key}_path": path, f"{key}_bytes": 0,
                f"{key}_size": "—", f"{key}_dim": None, f"{key}_corrupt": False,
                f"{key}_desc": "", f"{key}_status": STATUS_MISSING, f"{key}_quality": "—",
                f"{key}_format": None, f"{key}_decode_ok": None,
                f"{key}_mismatch": False, f"{key}_flags": {}}
    st, desc, flags = evaluate_image(pr, image_type)
    w, h = pr["w"], pr["h"]
    return {f"{key}_exists": True, f"{key}_path": path, f"{key}_bytes": pr["bytes"],
            f"{key}_size": format_size(pr["bytes"]),
            f"{key}_dim": f"{w}×{h}" if (w and h) else None,
            f"{key}_corrupt": bool(flags["corrupt"]), f"{key}_desc": desc,
            f"{key}_status": st,
            f"{key}_quality": classify_image_quality(w, h, image_type),
            f"{key}_format": pr["format"], f"{key}_decode_ok": pr["decode_ok"],
            f"{key}_mismatch": pr["mismatch"], f"{key}_flags": flags}


def _artwork_row_fields(lst):                                  ### NEW v0.19.1 B23 ###
    """Row fields of poster / folder / fanart, found with Kodi's names
    (resolve_artwork), plus <key>_style ("kodi"/"plain"), <key>_tried (names
    looked for) and art_style (the folder's naming style)."""
    vb = _video_basename(lst)
    fields = {"art_style": artwork_style(lst, vb)}
    for key in ("poster", "folder", "fanart"):
        r = resolve_artwork(lst, key, vb)
        fields.update(_image_row_fields(key, key, r["path"], r["exists"]))
        fields[f"{key}_style"] = r["style"]
        fields[f"{key}_tried"] = r["tried"]
    return {"fields": fields, "vb": vb}


def _art_found_line(d, key):                                   ### NEW v0.19.1 B23 ###
    """Tooltip header: the file that was found (and whether it is Kodi naming)."""
    name = os.path.basename(d.get(f"{key}_path") or "") or f"{key}.jpg"
    line = f"Found: {name}" + ("  (Kodi naming)" if d.get(f"{key}_style") == "kodi" else "")
    srv = d.get(f"{key}_servers")                                ### NEW v0.19.2 F5 — who reads this name ###
    if srv is not None:
        line += "\nRead by: " + (_nc.servers_text(srv) or "no media server (MediaClinic only)")
    for n in d.get("art_notes") or []:
        if n.lower().startswith(name.lower() + ":"):
            line += f"\n[!] {n}"
    if key == "poster" and d.get("extra_art"):
        line += "\nOther artwork (information only): " + ", ".join(d["extra_art"][:6])
    return line


def _art_missing_tip(d, key, expected):                        ### NEW v0.19.1 B23 ###
    """Tooltip for a missing poster / folder / fanart: where it would be
    written and every name Kodi (and MediaClinic) accepts."""
    lines = [f"{os.path.basename(expected) or key + '.jpg'}", "[MISSING]", f"Expected: {expected}"]
    tried = d.get(f"{key}_tried") or []
    if tried:
        lines.append("Looked for: " + ", ".join(tried))
    if key == "folder" and d.get("poster_exists") and d.get("poster_style") == "kodi":
        lines.append("Optional: Kodi uses the '<video>-poster' image "
                     "(Settings → Health Rules → folder.jpg optional)")
    return "\n".join(lines)


def reevaluate_row_images(row, settings=None):                 ### NEW v0.19.0 ###
    """Re-derive status / description / corrupt / quality of the three artwork
    files from the facts already stored on the row (no disk access).  Used on
    load, on Recompute Health and after Save & Apply, so a cached v0.18.x
    "corrupt" never survives: a row that has dimensions but no decode_ok
    field was parsed successfully and is treated as decodable."""
    for key, itype in (("poster", "poster"), ("folder", "folder"), ("fanart", "fanart")):
        if not row.get(f"{key}_exists"):
            row[f"{key}_corrupt"] = False
            row[f"{key}_status"]  = STATUS_MISSING
            row[f"{key}_desc"]    = ""
            row[f"{key}_flags"]   = {}
            continue
        w, h = _parse_dim_str(row.get(f"{key}_dim"))
        dec = row.get(f"{key}_decode_ok")
        if dec is None:
            dec = bool(w and h)
        pr = {"exists": True, "bytes": row.get(f"{key}_bytes") or 0,
              "format": row.get(f"{key}_format") or "JPEG",
              "ext_format": None, "w": w, "h": h, "decode_ok": dec,
              "mismatch": bool(row.get(f"{key}_mismatch"))}
        st, desc, flags = evaluate_image(pr, itype, settings)
        row[f"{key}_status"]  = st
        row[f"{key}_desc"]    = desc
        row[f"{key}_corrupt"] = bool(flags["corrupt"])
        row[f"{key}_flags"]   = flags
        row[f"{key}_quality"] = classify_image_quality(w, h, itype)
    return row

# ══════════════════════════════════════════════════════════════════════════════
# Backdrop helpers
# ══════════════════════════════════════════════════════════════════════════════

class _FolderListing:                                          ### NEW v0.18.4 ###
    """
    One os.scandir() per movie folder.  v0.18.3 listed each folder about six
    times (videos, subtitles, backdrops, mtime, plus isfile/getsize calls);
    on a network share every listing is a round-trip.  Lookups are case-
    insensitive so "Poster.JPG" is found on Linux too.
    """
    __slots__ = ("path", "files", "dirs", "disc_cache", "video_cache", "error")   ### video_cache v0.19.2 F5, error B53 ###

    def __init__(self, sub_path):
        self.path  = sub_path
        self.files = {}          # lower name -> (name, path, size, mtime)
        self.dirs  = {}          # lower name -> path (sub-folders, e.g. extrafanart)  ### NEW v0.19.1 B23 ###
        self.disc_cache = False  # _disc_info() result (False = not computed yet)      ### NEW v0.19.1 B23 ###
        self.video_cache = None  # classify_videos() result                             ### NEW v0.19.2 F5 ###
        self.error = None        # the OSError text when the folder could not be listed  ### NEW v0.19.2 B53 ###
        try:
            for e in os.scandir(sub_path):
                try:
                    if e.is_file():
                        st = e.stat()
                        self.files[e.name.lower()] = (e.name, e.path, st.st_size, st.st_mtime)
                    elif e.is_dir():
                        self.dirs[e.name.lower()] = e.path
                except OSError:
                    pass
        except OSError as ex:
            self.error = getattr(ex, "strerror", None) or str(ex)

    def has(self, name):
        return name.lower() in self.files

    def size(self, name):
        f = self.files.get(name.lower())
        return f[2] if f else 0

    def path_of(self, name):
        f = self.files.get(name.lower())
        return f[1] if f else os.path.join(self.path, name)

    def newest_mtime(self):
        return max((f[3] for f in self.files.values()), default=0.0)

    def by_ext(self, exts):
        return [f for f in self.files.values()
                if os.path.splitext(f[0])[1].lower() in exts]


def _subs_summary(subs_internal, subs_external, video_path, subs_hard=None):   ### NEW v0.18.4, subs_hard v0.19.1 B15 ###
    parts = []
    if subs_internal:
        parts.append("Int: " + ", ".join(s["lang"] for s in subs_internal))
    if subs_external:
        parts.append("Ext: " + ", ".join(s["lang"] for s in subs_external))
    if subs_hard:
        parts.append("Hard: " + ", ".join(subs_hard))
    return " | ".join(parts) if parts else ("None" if video_path else "—")


# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.19.1 B23 — Kodi naming (artwork + NFO), one resolver used everywhere
# ══════════════════════════════════════════════════════════════════════════════
# Kodi looks for local movie artwork in this order (CVideoThumbLoader; Kodi
# wiki "Movie artwork"): "<video file name>-<type>.<ext>" first, then — for a
# movie in its own folder — "<type>.<ext>"; the legacy poster ("thumb") also
# comes from "<video file name>.tbn" / "movie.tbn" (and folder.jpg).  Kodi's
# library export ("separate files") writes the "<video file name>-<type>"
# form.  The NFO is "<video file name>.nfo" or "movie.nfo".  MediaClinic now
# reads every one of these forms, shows the one Kodi would use, and writes in
# the naming style the folder already uses.
_ART_EXTS = _nc.ART_EXTS                                      ### MODIFIED v0.19.2 F5 — .jpeg / .webp / .gif / .bmp too ###
_KODI_ART_TYPES = ("poster", "fanart", "thumb", "landscape", "banner", "clearlogo",
                   "clearart", "discart", "keyart", "characterart")


def _video_basename(lst):
    """File name (without extension) of the main video — as scan_video_files
    picks it (### MODIFIED v0.19.2 F5 ### trailers, samples and extras are
    never the main video; a stack's main video is part 1) — or None."""
    main = classify_videos(lst)["main"]
    return os.path.splitext(main[0])[0] if main else None


def classify_videos(lst):                                       ### NEW v0.19.2 F5 ###
    """Sort the videos of a movie folder into the main video and the others
    the servers handle (naming_catalog.group_videos: trailers, samples,
    extras, the parts of a stack, versions / editions).  Returns {"main":
    file tuple | None, "kinds": {file name: kind}, "n_main": movies that
    remain (2+ = really "Multiple video files"), "group": "stack" /
    "versions" / None}.  Cached on the listing (no disk access)."""
    if lst.video_cache is not None:
        return lst.video_cache
    vids = lst.by_ext(VIDEO_EXTENSIONS)
    g = _nc.group_videos([(f[0], f[2]) for f in vids], os.path.basename(os.path.normpath(lst.path)))
    by_name = {f[0]: f for f in vids}
    lst.video_cache = {"main": by_name.get(g["main"]), "kinds": g["kinds"], "n_main": g["n_main"], "group": g["group"]}
    return lst.video_cache


def video_kinds_text(kinds):                                     ### NEW v0.19.2 F5 ###
    """{'a.mkv': 'trailer', …} → '+ 1 trailer, 2 extras' (tooltips)."""
    cnt = {}
    for k in kinds.values():
        cnt[k] = cnt.get(k, 0) + 1
    parts = [f"{n} {_nc.VIDEO_KIND_LABEL.get(k, k)}{'s' if n != 1 else ''}"
             for k, n in sorted(cnt.items(), key=lambda t: ("part", "version", "trailer", "sample", "extra").index(t[0])
                                if t[0] in ("part", "version", "trailer", "sample", "extra") else 9)]
    return ("+ " + ", ".join(parts)) if parts else ""


def _disc_info(lst):                                             ### NEW v0.19.1 B23 ###
    """DVD / Blu-ray folder structure of a movie folder, or None:
      {"type": "DVD"|"BD", "dir", "listing", "vb" ("VIDEO_TS"/"index"),
       "marker" (VIDEO_TS.IFO / index.bdmv), "probe" (largest .VOB / .m2ts,
       used for FFprobe and frames), "bytes" (total of those files)}.
    Kodi treats VIDEO_TS.IFO / index.bdmv as the movie file: file-based names
    (VIDEO_TS-poster.jpg, VIDEO_TS.nfo, index-poster.jpg, index.nfo) live
    next to it, folder-based names (poster.jpg, movie.nfo) in the movie
    folder.  A VIDEO_TS.IFO directly in the movie folder is a DVD too.
    Cached on the listing (one extra directory listing, only for disc folders)."""
    if lst.disc_cache is not False:
        return lst.disc_cache
    info = None
    try:
        for dname, kind, vb, marker, exts in (("video_ts", "DVD", "VIDEO_TS", "video_ts.ifo", (".vob",)),
                                               ("bdmv", "BD", "index", "index.bdmv", (".m2ts",))):
            if dname == "video_ts" and lst.has("video_ts.ifo"):
                dl = lst
            elif lst.dirs.get(dname):
                dl = _FolderListing(lst.dirs[dname])
            else:
                continue
            if not dl.has(marker):
                continue
            media_l = dl
            if kind == "BD" and dl.dirs.get("stream"):
                media_l = _FolderListing(dl.dirs["stream"])
            media = sorted(media_l.by_ext(set(exts)), key=lambda f: f[2], reverse=True)
            info = {"type": kind, "dir": dl.path, "listing": dl, "vb": vb,
                    "marker": dl.path_of(marker),
                    "probe": media[0][1] if media else dl.path_of(marker),
                    "bytes": sum(f[2] for f in media)}
            break
    except OSError:
        info = None
    lst.disc_cache = info
    return info


def artwork_style(lst, vb=None):
    """"kodi" when the folder already holds file-based Kodi artwork
    ("<video>-<type>.jpg/png", or "VIDEO_TS-<type>" / "index-<type>" next to
    a disc structure), else "plain" (poster.jpg / fanart.jpg)."""
    disc = _disc_info(lst)
    if disc:
        dl, dvb = disc["listing"], disc["vb"]
        return "kodi" if any(dl.has(f"{dvb}-{t}{e}") for t in _KODI_ART_TYPES for e in _ART_EXTS) else "plain"
    vb = vb if vb is not None else _video_basename(lst)
    if not vb:
        return "plain"
    return "kodi" if any(lst.has(f"{vb}-{t}{e}") for t in _KODI_ART_TYPES for e in _ART_EXTS) else "plain"


def _art_candidates(lst, kind, vb):
    """[(listing, name, kodi_style)] for kind, in reading order: Kodi's names
    first (B23 order unchanged), then — ### NEW v0.19.2 F5 ### — every other
    name Jellyfin, Emby or Plex read (naming_catalog: cover, default, movie,
    "<video>.jpg", backdrop / background / art as the main fanart …) and the
    extensions .jpeg / .webp / .gif / .bmp."""
    if kind == "folder":
        return [(lst, f"folder{e}", False) for e in _ART_EXTS]
    disc = _disc_info(lst)
    out = []
    if disc:
        out += [(disc["listing"], f"{disc['vb']}-{kind}{e}", True) for e in _ART_EXTS]
    elif vb:
        out += [(lst, f"{vb}-{kind}{e}", True) for e in _ART_EXTS]
    out += [(lst, f"{kind}{e}", False) for e in _ART_EXTS]
    if kind == "poster":
        if disc:
            out.append((disc["listing"], f"{disc['vb']}.tbn", True))
        elif vb:
            out.append((lst, f"{vb}.tbn", True))
        out.append((lst, "movie.tbn", True))
    seen = {(id(cl), n.lower()) for cl, n, _k in out}
    for pat, _srv in _nc.ART_NAMES.get(kind, ()):                ### NEW v0.19.2 F5 ###
        name = _nc.expand(pat, video=(disc["vb"] if disc else vb))
        if not name:
            continue
        cl = disc["listing"] if (disc and "{video}" in pat) else lst
        for e in _ART_EXTS:
            if (id(cl), f"{name}{e}".lower()) not in seen:
                seen.add((id(cl), f"{name}{e}".lower()))
                out.append((cl, f"{name}{e}", False))
    return out


def art_servers(name, kind, vb):                                 ### NEW v0.19.2 F5 ###
    """Servers that read *name* as the kind's main image (pattern ∩ extension)."""
    stem, ext = os.path.splitext(name)
    ext = ext.lower()
    pats = list(_nc.ART_NAMES.get(kind, ())) + (list(_nc.POSTER_TBN) if kind == "poster" else [])
    servers = set()
    for pat, srv in pats:
        if pat.endswith(".tbn"):
            if name.lower() == (_nc.expand(pat, video=vb) or "").lower():
                servers |= set(srv)
            continue
        want = (_nc.expand(pat, video=vb) or "").lower()
        if want and stem.lower() == want:
            servers |= {s for s in srv if ext in _nc.SERVER_ART_EXTS[s]}
    if kind == "folder" and stem.lower() == "folder":
        servers = {s for s in _nc.SERVERS if ext in _nc.SERVER_ART_EXTS[s]}
    return [s for s in _nc.SERVERS if s in servers]


def _cand_label(lst, cl, name):
    """Name as shown in tooltips: relative to the movie folder."""
    return name if cl is lst else os.path.join(os.path.basename(cl.path), name)


def resolve_artwork(lst, kind, vb=None):
    """{path, exists, name, style, tried} for poster / fanart / folder.
    Missing → path is where it would be written in the folder's style."""
    vb = vb if vb is not None else _video_basename(lst)
    cands = _art_candidates(lst, kind, vb)
    tried = [_cand_label(lst, cl, n) for cl, n, _k in cands]
    for cl, n, kodi in cands:
        if cl.has(n):
            return {"path": cl.path_of(n), "exists": True, "name": cl.files[n.lower()][0],
                    "style": "kodi" if kodi else "plain", "tried": tried}
    disc = _disc_info(lst)
    if kind != "folder" and artwork_style(lst, vb) == "kodi":
        if disc:
            path = os.path.join(disc["dir"], f"{disc['vb']}-{kind}.jpg")
        else:
            path = os.path.join(lst.path, f"{vb}-{kind}.jpg")
        style = "kodi"
    else:
        path, style = os.path.join(lst.path, f"{kind}.jpg"), "plain"
    return {"path": path, "exists": False, "name": os.path.basename(path), "style": style, "tried": tried}


def artwork_write_target(sub_path, kind):
    """(target_path, path_to_remove_after_success | None) for writing a new
    JPEG poster / fanart / folder image in the folder's naming style:
    an existing .jpg is overwritten; an existing .png is replaced by the
    .jpg of the same name (the .png is removed after the download, so Kodi
    does not keep showing it); a legacy .tbn poster is kept and the modern
    file-based name ("<video>-poster.jpg", "VIDEO_TS-poster.jpg",
    "index-poster.jpg") is written, which Kodi prefers."""
    lst = _FolderListing(sub_path)
    vb = _video_basename(lst)
    r = resolve_artwork(lst, kind, vb)
    if r["exists"]:
        base, ext = os.path.splitext(r["path"])
        if ext.lower() in (".jpg", ".jpeg"):                   ### .jpeg v0.19.2 F5 — JPEG data, same name ###
            return r["path"], None
        if ext.lower() in (".png", ".webp", ".gif", ".bmp"):   ### .webp/.gif/.bmp v0.19.2 F4/F5 — like .png ###
            return base + ".jpg", r["path"]
        disc = _disc_info(lst)                          # .tbn → keep it, write the modern name
        if disc:
            return os.path.join(disc["dir"], f"{disc['vb']}-{kind}.jpg"), None
        if vb:
            return os.path.join(sub_path, f"{vb}-{kind}.jpg"), None
        return os.path.join(sub_path, f"{kind}.jpg"), None
    return r["path"], None


def artwork_targets_for_fetch(sub_path, mode):                 ### NEW v0.19.1 B23 ###
    """(targets, to_remove) for Fetch Poster/Folder (mode "poster") or Fetch
    Fanart (mode "fanart"): the poster/fanart in the folder's naming style;
    folder.jpg too in poster mode when it exists, when the folder uses the
    plain style, or when Health Rules → "folder.jpg optional" is off."""
    kind = "poster" if mode == "poster" else "fanart"
    main, rm = artwork_write_target(sub_path, kind)
    targets, to_remove = [main], ([rm] if rm else [])
    if kind == "poster":
        lst = _FolderListing(sub_path)
        fold = resolve_artwork(lst, "folder")
        rules = SETTINGS.get("health_rules", {}) or {}
        if fold["exists"] or artwork_style(lst) == "plain" or not rules.get("folder_optional_with_kodi_poster", True):
            ft, frm = artwork_write_target(sub_path, "folder")
            targets.append(ft)
            if frm:
                to_remove.append(frm)
    return targets, to_remove


def _poster_folder_differ(row):                                ### NEW v0.19.1 B23 ###
    """True when poster and folder image (both present) are different images:
    different byte sizes — except when the formats differ (a Kodi poster.png
    or movie.tbn next to folder.jpg can never share a byte size), where the
    same dimensions count as the same image."""
    pb, fb = row.get("poster_bytes", 0), row.get("folder_bytes", 0)
    if not (pb and fb) or pb == fb:
        return False
    pf, ff = row.get("poster_format"), row.get("folder_format")
    if pf and ff and pf != ff and row.get("poster_dim") and row.get("poster_dim") == row.get("folder_dim"):
        return False
    return True


def _copy_image_as(src, dest):                                 ### NEW v0.19.1 B23 ###
    """Copy an image; when the destination extension needs another format
    (e.g. a Kodi poster.png or movie.tbn copied to folder.jpg) it is
    re-encoded with Pillow instead of copied byte for byte (no extension
    mismatch).  Written atomically through a temp file."""
    want = {".jpg": "JPEG", ".jpeg": "JPEG", ".png": "PNG"}.get(os.path.splitext(dest)[1].lower())
    have = (probe_image(src) or {}).get("format")
    if not want or want == have or not _PIL_AVAILABLE:
        shutil.copy2(src, dest)
        return
    tmp = dest + ".mctmp"
    with _PILImage.open(src) as im:
        im = im.convert("RGB") if want == "JPEG" else im
        im.save(tmp, want, **({"quality": 95} if want == "JPEG" else {}))
    os.replace(tmp, dest)


