def naming_row_fields(lst, sub_name, vb=None):                   ### NEW v0.19.2 F5 ###
    """Row fields from the names in the folder (no extra disk access, except
    comparing NFO contents when there are several):
      nfo_all (names of every readable NFO, the used one first), nfo_all_differ,
      xml_notes (mymovies.xml …), art_notes (Kodi name case …),
      extra_art (clearlogo, landscape … — information only),
      poster_servers / fanart_servers / folder_servers (who reads the file found)."""
    vb = vb if vb is not None else _video_basename(lst)
    nfos = readable_nfos(lst, sub_name, vb)
    differ = False
    if len(nfos) > 1:
        try:
            contents = {open(p, "rb").read() for _n, p in nfos}
            differ = len(contents) > 1
        except OSError:
            differ = False
    xml_notes = []
    for old in _nc.OLD_XML_NAMES:
        if lst.has(old):
            xml_notes.append(f"{lst.files[old][0]} found — no current server reads it (it is not movie.xml; "
                             f"convert it by hand if you need the data)")
    art_notes, servers = [], {}
    for key in ("poster", "fanart", "folder"):
        r = resolve_artwork(lst, key, vb)
        if not r["exists"]:
            continue
        servers[f"{key}_servers"] = art_servers(r["name"], key, vb)
        if vb and r["name"].lower().startswith(vb.lower() + "-") and not r["name"].startswith(vb + "-"):
            art_notes.append(f"{r['name']}: Kodi matches '<video>-{key}' case-sensitively — "
                             f"rename it to '{vb}-{key}…' for Kodi")
    extra = sorted({f[0] for f in lst.files.values()
                    if os.path.splitext(f[0])[1].lower() in _ART_EXTS
                    and (os.path.splitext(f[0])[0].lower() in _nc.EXTRA_ART_KINDS
                         or (vb and os.path.splitext(f[0])[0].lower().startswith(vb.lower() + "-")
                             and os.path.splitext(f[0])[0].lower()[len(vb) + 1:] in _nc.EXTRA_ART_KINDS))})
    extra_dirs = sorted(lst.dirs[d].rsplit(os.sep, 1)[-1] for d in lst.dirs if d in _nc.EXTRA_FOLDERS)
    return {"nfo_all": [n for n, _p in nfos], "nfo_all_differ": differ, "xml_notes": xml_notes,
            "art_notes": art_notes, "extra_art": extra, "extra_dirs": extra_dirs, **servers}


def backdrop_naming(sub_path):                                  ### NEW v0.19.1 B23 ###
    """("plain"|"kodi", listing, video basename) — how new backdrops are named."""
    lst = _FolderListing(sub_path)
    vb = _video_basename(lst)
    return artwork_style(lst, vb), lst, vb


def new_backdrop_paths(sub_path, n):                            ### NEW v0.19.1 B23 ###
    """n free paths for new backdrops in the folder's naming style:
    plain (Emby/Jellyfin) → backdrop.jpg, backdrop1.jpg …;
    Kodi → "<video>-fanart1.jpg" … (a disc structure: fanart1.jpg … in the
    movie folder).  Numbers already used by any backdrop/fanart name are
    skipped."""
    style, lst, vb = backdrop_naming(sub_path)
    names = set(lst.files)
    out = []
    if style == "kodi":
        prefix = "" if (_disc_info(lst) or not vb) else f"{vb}-"
        used = set()
        for f in names:
            m = re.match(r'^(?:.*-)?fanart(\d+)\.(?:jpg|png)$', f)
            if m:
                used.add(int(m.group(1)))
        k = 1
        while len(out) < n:
            if k not in used:
                out.append(os.path.join(sub_path, f"{prefix}fanart{k}.jpg"))
            k += 1
        return out
    used = {int(m.group(1)) for f in names for m in [re.match(r'^backdrop(\d+)\.jpg$', f)] if m}
    if "backdrop.jpg" not in names and len(out) < n:
        out.append(os.path.join(sub_path, "backdrop.jpg"))
    k = 1
    while len(out) < n:
        if k not in used:
            out.append(os.path.join(sub_path, f"backdrop{k}.jpg"))
        k += 1
    return out


def replaceable_backdrops(sub_path):                            ### NEW v0.19.1 B23 ###
    """The backdrop files Replace All Backdrops replaces: backdrop*.jpg in a
    plain folder; Kodi extra fanart (fanartN, "<video>-fanartN", the
    extrafanart folder) in a Kodi-style folder.  Never the main fanart."""
    style, lst, vb = backdrop_naming(sub_path)
    _n, paths, _a = count_backdrops(sub_path, listing=lst)
    if style == "kodi":
        return [p for p in paths if not re.match(r'^backdrop\d*\.jpg$', os.path.basename(p).lower())]
    return [p for p in paths if re.match(r'^backdrop\d*\.jpg$', os.path.basename(p).lower())
            and os.path.dirname(p) == sub_path]


def count_backdrops(sub_path, listing=None):                     ### MODIFIED v0.18.4 — listing ###
    ### UPDATED v0.18.0 — scan all backdrop*.jpg; no longer stops at first gap ###
    ### MODIFIED v0.19.1 B23 — Kodi extra fanart counts too: fanart1.jpg…,
    ### "<video>-fanart1.jpg"…, and the images in an "extrafanart" sub-folder ###
    lst = listing or _FolderListing(sub_path)
    vb = (_video_basename(lst) or "").lower()
    paths = []
    sizes = {}
    _kodi_rx = re.compile(r'^(?:' + (re.escape(vb) + '-' if vb else '') + r')?fanart(\d+)\.(?:jpg|png)$') if vb \
        else re.compile(r'^fanart(\d+)\.(?:jpg|png)$')
    # ### MODIFIED v0.19.2 F5 ### every name the servers read as an extra backdrop
    # (backdrop-N, fanart-N, background(-N), art-N …) in every picture extension
    _exts = "|".join(e.lstrip(".") for e in _ART_EXTS)
    _bk_rx = re.compile(r"^(?:" + "|".join(p.replace("{video}", re.escape(vb)) for p in _nc.BACKDROP_STEM_PATTERNS
                                         if vb or "{video}" not in p) + r")\.(?:" + _exts + r")$")
    for name, path, size, _m in lst.files.values():
        n = name.lower()
        if n == "backdrop.jpg" or re.match(r'^backdrop\d+\.jpg$', n) or _kodi_rx.match(n) or _bk_rx.match(n):
            paths.append(path); sizes[path] = size
    _disc = _disc_info(lst)                                      ### NEW v0.19.1 B23 — VIDEO_TS-fanart1.jpg … ###
    if _disc and _disc["listing"] is not lst:
        _drx = re.compile(r'^' + re.escape(_disc["vb"].lower()) + r'-fanart(\d+)\.(?:jpg|png)$')
        for name, path, size, _m in _disc["listing"].files.values():
            if _drx.match(name.lower()):
                paths.append(path); sizes[path] = size
    _xf = lst.dirs.get("extrafanart")
    if _xf:
        try:
            for e in os.scandir(_xf):
                if e.is_file() and os.path.splitext(e.name)[1].lower() in _ART_EXTS:
                    paths.append(e.path); sizes[e.path] = e.stat().st_size
        except OSError:
            pass
    # Sort deterministically: backdrop.jpg, backdrop1…, then Kodi fanart1…, then extrafanart
    def _sort_key(p):
        n = os.path.basename(p).lower()
        if os.path.dirname(p) != lst.path and os.path.basename(os.path.dirname(p)).lower() == "extrafanart":
            return (3, n)
        if n == "backdrop.jpg":
            return (0, -1)
        m = re.match(r'^backdrop(\d+)\.jpg$', n)
        if m:
            return (0, int(m.group(1)))
        m = _kodi_rx.match(n)
        return (2, int(m.group(1))) if m else (9, n)
    paths.sort(key=_sort_key)
    count = len(paths)
    total_bytes = sum(sizes.get(p, 0) for p in paths)
    avg_bytes = (total_bytes // count) if count > 0 else 0          ### NEW v0.15.0 ###
    return count, paths, avg_bytes                                   ### NEW v0.15.0 ###

def next_backdrop_number(sub_path):
    ### UPDATED v0.18.0 — find first unused slot even when numbers have gaps ###
    if not os.path.isfile(os.path.join(sub_path, "backdrop.jpg")):
        return 0
    used = set()
    try:
        for entry in os.scandir(sub_path):
            if not entry.is_file():
                continue
            m = re.match(r'^backdrop(\d+)\.jpg$', entry.name.lower())
            if m:
                used.add(int(m.group(1)))
    except OSError:
        pass
    i = 1
    while i in used:
        i += 1
    return i

# ══════════════════════════════════════════════════════════════════════════════
# Video / subtitle / language helpers
