def _pkey(path):                                               ### NEW v0.18.3 ###
    """Normalised dict key for a folder path (forward and back slashes compare equal)."""
    try:
        return os.path.normcase(os.path.normpath(path or ""))
    except Exception:
        return path or ""


def _folder_mtime(sub_path, listing=None):                     ### NEW v0.18.3, listing v0.18.4 ###
    """Newest modification time (float seconds) among the files directly in
    *sub_path*, or 0.  Stored per row as scan_mtime so Quick Scan can detect
    modified movies by comparing against the value recorded at scan time."""
    return (listing or _FolderListing(sub_path)).newest_mtime()


def scan_video_files(sub_path, listing=None):                  ### MODIFIED v0.18.4 — listing ###
    lst = listing or _FolderListing(sub_path)
    videos = sorted(lst.by_ext(VIDEO_EXTENSIONS), key=lambda f: f[2], reverse=True)
    if not videos:
        disc = _disc_info(lst)                                   ### NEW v0.19.1 B23 — DVD / Blu-ray folders ###
        if disc:
            rel = os.path.relpath(disc["marker"], sub_path)
            return {"video_count":1,"video_files":[rel],
                    "video_ext":"DVD" if disc["type"] == "DVD" else "BLU-RAY",
                    "video_path":disc["probe"],"video_bytes":disc["bytes"],
                    "video_size":format_size(disc["bytes"]),
                    "video_width":None,"video_height":None,"video_quality":"—"}
        return {"video_count":0,"video_files":[],"video_ext":"—",
                "video_path":None,"video_bytes":0,"video_size":"—",
                "video_width":None,"video_height":None,"video_quality":"—"}
    cv = classify_videos(lst)                                    ### MODIFIED v0.19.2 F5 — trailers, extras, stacks, versions ###
    name, path, size, _m = cv["main"]
    ext = os.path.splitext(name)[1].lower()
    # Quality determined later when ffprobe runs (phased scan)
    return {"video_count":cv["n_main"],"video_files":[name] + [v[0] for v in videos if v[0] != name],
            "video_kinds":dict(cv["kinds"]),"video_group":cv["group"],
            "video_ext":ext.lstrip('.').upper(),"video_path":path,
            "video_bytes":size,"video_size":format_size(size),
            "video_width":None,"video_height":None,"video_quality":"—"}

def _ffprobe_enabled(flag=None):
    """True when ffprobe may run: a path exists and the flag (or the global
    setting when flag is None) allows it.                    ### NEW v0.18.3 ###"""
    if not FFPROBE_PATH:
        return False
    return bool(SETTINGS.get("use_ffprobe", True)) if flag is None else bool(flag)


# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.19.1 I5 — ONE ffprobe per video, cached (ffprobe_cache.json)
# ══════════════════════════════════════════════════════════════════════════════
# v0.19.0 ran four ffprobe processes per video and scan (resolution, audio,
# subtitles, the Lang OK? audio check).  Now one "-show_streams -show_format"
# call gives everything, and the result is kept per path + size + mtime_ns, so
# an unchanged video is never probed again (network shares!).  "Update (with
# FFprobe)" forces a fresh probe.  Setting: ffprobe_cache_enabled.
_FFPROBE_CACHE = None                       # loaded lazily from settings_controller
_FFPROBE_LOCK = threading.Lock()
_FFPROBE_DIRTY = [False]
_FFPROBE_STATS = {"runs": 0, "hits": 0}     # self-test spy
_FFPROBE_MEMO = {}                          # cache OFF: result kept ~10 s (one movie's scan), never saved
_FFPROBE_MEMO_TTL = 10.0


def _ffprobe_cache():
    global _FFPROBE_CACHE
    with _FFPROBE_LOCK:
        if _FFPROBE_CACHE is None:
            _FFPROBE_CACHE = _sc.load_ffprobe_cache()
        return _FFPROBE_CACHE


def _run_ffprobe_json(video_path, timeout=30):
    """The one ffprobe process: -show_streams -show_format → dict ({} on failure)."""
    _FFPROBE_STATS["runs"] += 1
    try:
        status, rc, out, _err = _run_ffmpeg(                    ### MODIFIED v0.19.2 B28 — runner: priority, killed on close ###
            [FFPROBE_PATH, "-v", "quiet", "-print_format", "json",
             "-show_streams", "-show_format", video_path], timeout)
        if status == FF_OK and rc == 0 and out.strip():
            d = json.loads(out)
            return d if isinstance(d, dict) else {}
    except Exception:
        pass
    return {}


def _probe_json(video_path, use_ffprobe=None, force=False):     ### NEW v0.19.1 I5 ###
    """FFprobe data of *video_path* (format + streams), from the cache when
    the file's size and mtime_ns are unchanged.  force=True probes again."""
    if not video_path or not _ffprobe_enabled(use_ffprobe):
        return {}
    try:
        st = os.stat(video_path)
    except OSError:
        return {}
    key = os.path.normcase(os.path.abspath(video_path))
    use_cache = bool(SETTINGS.get("ffprobe_cache_enabled", True))
    if use_cache and not force:
        e = _ffprobe_cache().get(key)
        if e and e.get("size") == st.st_size and e.get("mtime_ns") == st.st_mtime_ns:
            _FFPROBE_STATS["hits"] += 1
            return e["data"]
    if not use_cache and not force:                     # still ONE probe per video and scan
        m = _FFPROBE_MEMO.get(key)
        if m and m[0] == (st.st_size, st.st_mtime_ns) and time.time() - m[1] < _FFPROBE_MEMO_TTL:
            return m[2]
    data = _run_ffprobe_json(video_path)
    if data and not use_cache:
        _FFPROBE_MEMO[key] = ((st.st_size, st.st_mtime_ns), time.time(), data)
        if len(_FFPROBE_MEMO) > 256:
            _FFPROBE_MEMO.clear()
    if data and use_cache:
        c = _ffprobe_cache()
        with _FFPROBE_LOCK:
            c[key] = {"size": st.st_size, "mtime_ns": st.st_mtime_ns, "data": data}
            _FFPROBE_DIRTY[0] = True
    return data


def _ffprobe_cache_flush():                                     ### NEW v0.19.1 I5 ###
    """Save the cache when it changed (worker threads; called after scans)."""
    if not _FFPROBE_DIRTY[0] or _FFPROBE_CACHE is None:
        return
    with _FFPROBE_LOCK:
        snap = dict(_FFPROBE_CACHE)
        _FFPROBE_DIRTY[0] = False
    try:
        _sc.save_ffprobe_cache(snap)
    except Exception as ex:
        logger.warning(f"ffprobe_cache.json not saved: {ex}")


def _probe_streams(video_path, kind, use_ffprobe=None):         ### NEW v0.19.1 I5 ###
    """Streams of one codec_type ("video" / "audio" / "subtitle")."""
    return [s for s in (_probe_json(video_path, use_ffprobe).get("streams") or [])
            if s.get("codec_type") == kind]


def _get_video_resolution(video_path, use_ffprobe=None):
    """Return (width, height) of first video stream, or (None, None).
    ### MODIFIED v0.19.1 I5 — from the one cached probe ###"""
    for s in _probe_streams(video_path, "video", use_ffprobe):
        w = s.get("width"); h = s.get("height")
        if w and h:
            return int(w), int(h)
        break
    return None, None

def _get_ffprobe_full(video_path, use_ffprobe=None):
    """Return full ffprobe JSON dict (format + streams), or {}.
    ### MODIFIED v0.19.1 I5 — the one cached probe ###"""
    return _probe_json(video_path, use_ffprobe)

def scan_subtitles(sub_path, video_path, use_ffprobe=None, listing=None):  ### MODIFIED v0.18.4 — listing ###
    result = {"subs_internal":[],"subs_external":[],"subs_summary":"—"}
    lst = listing or _FolderListing(sub_path)
    vstem = os.path.splitext(os.path.basename(video_path))[0] if video_path else None   ### MODIFIED v0.19.2 F5 ###
    _sub_lists = [("", lst)]
    if lst.dirs.get(_nc.SUBS_DIR):                               # Kodi: Subs\ next to the video
        _sub_lists.append(("Subs\\", _FolderListing(lst.dirs[_nc.SUBS_DIR])))
    for prefix, sl in _sub_lists:
        for name, _p, _s, _m in sorted(sl.by_ext(SUBTITLE_EXTENSIONS)):
            lang, flags = _nc.parse_subtitle_name(os.path.splitext(name)[0], vstem)
            ent = {"lang": lang, "file": prefix + name}
            if flags:
                ent["flags"] = flags
            result["subs_external"].append(ent)
    if video_path and _ffprobe_enabled(use_ffprobe):
        for stream in _probe_streams(video_path, "subtitle", use_ffprobe):   ### MODIFIED v0.19.1 I5 ###
            tags = stream.get("tags", {})
            result["subs_internal"].append({
                "lang":  tags.get("language") or tags.get("LANGUAGE") or "und",
                "title": tags.get("title")    or tags.get("TITLE")    or ""})
    result["subs_summary"] = _subs_summary(result["subs_internal"], result["subs_external"], video_path)
    return result
def _lang3(value):                                              ### NEW v0.19.1 B16 ###
    """'por' / 'pt' / 'Portuguese' / 'pt-BR' → 'POR'; None when unknown or undefined."""
    v = (value or "").strip().lower()
    if not v or v in ("und", "undefined", "unknown", "zxx", "mis", "mul"):
        return None
    if re.fullmatch(r"[a-z]{3}", v):
        return v.upper()
    for iso2, aliases in _LANG_ALIASES.items():
        if v in aliases:
            return normalize_lang_code(iso2)
    if re.fullmatch(r"[a-z]{2}", v):
        return normalize_lang_code(v)
    return None


def _file_audio_langs(nfo_path, xml_path):                      ### NEW v0.19.1 B16 ###
    """Audio-language candidate lists from the files, in order of trust:
    [("NFO", fileinfo/streamdetails/audio/language…), ("XML", Audio/Language…),
     ("NFO", video/language…)].  Unknown / undefined values are dropped."""
    out = []
    nroot = _parse_root(nfo_path) if nfo_path and os.path.isfile(nfo_path) else None
    xroot = _parse_root(xml_path) if xml_path and os.path.isfile(xml_path) else None
    if nroot is not None:
        out.append(("NFO", [c for c in (_lang3(a.findtext("language")) for a in nroot.iter("audio")) if c]))
    if xroot is not None:
        out.append(("XML", [c for c in (_lang3(a.findtext("Language")) for a in xroot.iter("Audio")) if c]))
    if nroot is not None:
        out.append(("NFO", [c for c in (_lang3(v.findtext("language")) for v in nroot.iter("video")) if c]))
    return [(src, lst) for src, lst in out if lst]


def fill_audio_lang_from_files(tracks, nfo_path, xml_path):     ### NEW v0.19.1 B16 ###
    """FFprobe stays primary: only tracks whose language is UND/empty get one
    from the NFO/XML — by position when the file lists as many languages as
    there are tracks, the single language when there is one undefined track
    and one language, or the common language when all listed ones are equal.
    Otherwise the track stays UND (no guessing).  A filled track carries
    language_src ("NFO"/"XML") and language_raw (what FFprobe said), so it is
    re-filled from scratch every time (an edited NFO is picked up).  Nothing
    is written to the files.  Returns a new list."""
    base = []
    for t in tracks or []:
        t = dict(t)
        if t.get("language_src"):                    # undo an earlier fill
            t["language"] = t.pop("language_raw", "UND") or "UND"
            t.pop("language_src", None)
        base.append(t)
    und = [i for i, t in enumerate(base) if (t.get("language") or "UND").upper() in ("UND", "")]
    if not und:
        return base
    for src, langs in _file_audio_langs(nfo_path, xml_path):
        if len(langs) == len(base):
            pick = {i: langs[i] for i in und}
        elif len(und) == 1 and len(langs) == 1:
            pick = {und[0]: langs[0]}
        elif len(langs) >= 2 and len(set(langs)) == 1:   # several listed, all equal
            pick = {i: langs[0] for i in und}
        else:
            continue
        for i, code in pick.items():
            base[i]["language_raw"] = base[i].get("language") or "UND"
            base[i]["language"] = code
            base[i]["language_src"] = src
        return base
    return base


def _refill_audio_row(r):                                       ### NEW v0.19.1 B16 ###
    """Apply fill_audio_lang_from_files to a row; a filled target-language
    track also makes Lang OK? = Y."""
    nfo = r.get("nfo_path") if r.get("nfo_exists") else None
    xml = r.get("xml_path") if r.get("xml_exists") else None
    if not r.get("audio_tracks"):
        return r
    r["audio_tracks"] = fill_audio_lang_from_files(r["audio_tracks"], nfo, xml)
    if r.get("video_path") and r.get("lang_ok") == "N":
        iso = SETTINGS.get("lang_ok_code", "PT")
        if any(t.get("language_src") and is_target_lang(t["language"], iso) for t in r["audio_tracks"]):
            r["lang_ok"] = "Y"
    return r


def scan_audio_tracks(video_path, use_ffprobe=None):             ### NEW v0.15.0 ###
    """
    Extract audio tracks from video_path using ffprobe.
    Returns list of dicts: [{language, codec, channels, bitrate}, ...]
    Only runs if FFPROBE_PATH is available.
    """
    if not video_path or not _ffprobe_enabled(use_ffprobe):
        return []
    try:
        tracks = []
        for stream in _probe_streams(video_path, "audio", True):   ### MODIFIED v0.19.1 I5 — the one cached probe ###
            tags    = stream.get("tags", {})
            lang    = (tags.get("language") or tags.get("LANGUAGE") or
                       tags.get("lang") or "und").upper()
            codec   = (stream.get("codec_name") or "").upper()
            # Channels
            ch_layout = stream.get("channel_layout", "")
            channels_int = stream.get("channels", 0)
            if ch_layout:
                _ch_map = {"mono": "1.0", "stereo": "2.0",
                           "2.1": "2.1", "3.0": "3.0",
                           "4.0": "4.0", "5.0": "5.0",
                           "5.1": "5.1", "6.0": "6.0",
                           "6.1": "6.1", "7.0": "7.0",
                           "7.1": "7.1"}
                channels = _ch_map.get(ch_layout.lower(), ch_layout)
            elif channels_int:
                _int_map = {1:"1.0",2:"2.0",3:"2.1",4:"4.0",5:"5.0",6:"5.1",
                            7:"6.1",8:"7.1"}
                channels = _int_map.get(channels_int, str(channels_int))
            else:
                channels = ""
            # Bitrate (kbps)
            br_raw = stream.get("bit_rate") or stream.get("BIT_RATE")
            try:
                bitrate = int(int(br_raw) / 1000) if br_raw else None
            except Exception:
                bitrate = None
            tracks.append({
                "language": lang, "codec": codec,
                "channels": channels, "bitrate": bitrate})
        return tracks
    except Exception:
        return []



def compute_lang_ok(video_path, subs_internal, subs_external, nfo_path, xml_path,
                    iso_code="PT", use_ffprobe=None, subs_hard=None):
    """
    Y  — target language audio OR subtitle is present (ffprobe + XML + NFO)
    N  — video present but no target language found
    —  — no video file
    subs_hard — hard-coded subtitle codes marked by the user (v0.19.1 B15)
    """
    if not video_path:
        return "—"

    # 0. Hard-coded subtitles marked by the user (no probe needed) ### NEW v0.19.1 B15 ###
    for c in (subs_hard or []):
        if is_target_lang(c, iso_code):
            return "Y"

    # 1. FFprobe audio streams (the one cached probe — v0.19.1 I5)
    if _ffprobe_enabled(use_ffprobe):
        for stream in _probe_streams(video_path, "audio", use_ffprobe):
            tags = stream.get("tags", {})
            lang = tags.get("language") or tags.get("LANGUAGE") or ""
            if is_target_lang(lang, iso_code):
                return "Y"

    # 2. Internal subtitles (ffprobe)
    for s in subs_internal:
        if is_target_lang(s.get("lang", ""), iso_code):
            return "Y"

    # 3. External subtitle files
    for s in subs_external:
        if is_target_lang(s.get("lang", ""), iso_code):
            return "Y"

    # 4. XML: LanguageCode tag
    if xml_path and os.path.isfile(xml_path):
        try:
            content = _read_text(xml_path) or ""
            for m in re.finditer(r'<LanguageCode>([^<]+)</LanguageCode>', content, re.IGNORECASE):
                if is_target_lang(m.group(1).strip(), iso_code): return "Y"
            # XML Audio/Language
            for m in re.finditer(r'<Language>([^<]+)</Language>', content, re.IGNORECASE):
                if is_target_lang(m.group(1).strip(), iso_code): return "Y"
        except Exception: pass

    # 5. NFO: streamdetails/video/language
    if nfo_path and os.path.isfile(nfo_path):
        try:
            content = _read_text(nfo_path) or ""
            for m in re.finditer(r'<language>([^<]+)</language>', content, re.IGNORECASE):
                if is_target_lang(m.group(1).strip(), iso_code): return "Y"
        except Exception: pass

    return "N"

def extract_language_from_xml(filepath):
    if not filepath or not os.path.isfile(filepath): return "—"
    try:
        content = _read_text(filepath) or ""
        m = re.search(r'<Language>([^<]+)</Language>', content)
        if m:
            lang = m.group(1).strip()
            return lang if lang else "Unknown"
        if '<Language></Language>' in content or '<Language />' in content:
            return "Unknown"
        return "—"
    except Exception: return "—"

# ══════════════════════════════════════════════════════════════════════════════
# XML / NFO parsing helpers
# ══════════════════════════════════════════════════════════════════════════════

def _is_url_only_nfo(content):
    s = content.strip()
    return '\n' not in s and s.startswith(('http://', 'https://'))

### NEW v0.10.0 — fast pre-check before full XML parse ###
def _fast_precheck_xml(filepath):
    """
    Fast pre-check: file exists, non-zero, starts with < or BOM.
    Returns (ok: bool, reason: str).
    """
    if not os.path.isfile(filepath):
        return False, "File not found"
    try:
        size = os.path.getsize(filepath)
        if size == 0:
            return False, "File is empty (0 bytes)"
        with open(filepath, "rb") as f:
            head = f.read(min(64, size))
        # Allow BOM, XML declaration, or direct tag
        stripped = head.lstrip(b"\xef\xbb\xbf \t\r\n")
        if not stripped.startswith(b"<"):
            return False, "File does not appear to be XML (no < found near start)"
        return True, ""
    except Exception as e:
        return False, str(e)


_ENTITY_RE = re.compile(r'&(?:amp|lt|gt|quot|apos|#\d+|#x[0-9A-Fa-f]+);')     ### NEW v0.19.1 B12 ###

### NEW v0.19.2 B33 — unescaped `&` in an NFO: warning rule + Auto Repair fix ###
# Kodi tolerates a bare `&`, but Jellyfin can ignore the WHOLE NFO because of
# one.  The scan's info note (scan_xml_structure) feeds the health rule.
AMP_NOTE_PREFIX = "`&` not escaped"
_BARE_AMP_RE = re.compile(r"&(?!(?:amp|lt|gt|quot|apos|#\d+|#x[0-9A-Fa-f]+);)([A-Za-z][A-Za-z0-9]{1,31};)?")
_AMP_SKIP_RE = re.compile(r"<!--.*?-->|<!\[CDATA\[.*?\]\]>", re.S)


def nfo_has_unescaped_amp(row):                                ### NEW v0.19.2 B33 ###
    return bool(row.get("nfo_exists")) and any(
        str(e.get("message", "")).startswith(AMP_NOTE_PREFIX) for e in (row.get("nfo_infos") or []))


def fix_unescaped_amp(text):                                   ### NEW v0.19.2 B33 ###
    """Pure: every bare `&` → `&amp;` (comments and CDATA untouched); a
    known HTML entity such as `&eacute;` (not valid XML either) becomes its
    character instead, so the text shown stays the same.  `&amp;`, `&#38;`
    … are kept.  Returns (new_text, number_of_changes)."""
    def _fix(seg):
        def rep(m):
            ent = m.group(1)
            if ent:
                ch = html.unescape("&" + ent)
                return _xml_text(ch) if ch != "&" + ent else "&amp;" + ent
            return "&amp;"
        return _BARE_AMP_RE.subn(rep, seg)
    out, n, pos = [], 0, 0
    for m in _AMP_SKIP_RE.finditer(text):
        s, k = _fix(text[pos:m.start()])
        out += [s, m.group(0)]; n += k; pos = m.end()
    s, k = _fix(text[pos:])
    out.append(s)
    return "".join(out), n + k


def _write_amp_fix(nfo_path):                                   ### NEW v0.19.2 B33 ###
    """Escape the bare `&` of an NFO (the caller makes the backup).
    Returns (ok, number_of_changes | error)."""
    try:
        text, _bom = _read_for_edit(nfo_path)
        new, n = fix_unescaped_amp(text)
        if not n:
            return True, 0
        if _parse_root(nfo_path) is not None:                   # parsed before → must parse strictly now
            ET.fromstring(new.lstrip("﻿"))
        _atomic_write_text(nfo_path, new)
        return True, n
    except Exception as e:
        return False, f"{os.path.basename(nfo_path)}: {e}"
_TAGNAME_RE = re.compile(r'[A-Za-z_][\w.\-:]*')


def scan_xml_structure(content):                                ### NEW v0.19.1 B12 ###
    """Tolerant tag-stack scan of an NFO/XML text that does NOT stop at the
    first problem (Python's parser does).  Returns (errors, infos), lists of
    {"line", "col", "message"} (1-based line/col; the message never starts
    with "Line …", the displays add that):
      • "`<plot>` opened here is never closed (expected `</plot>` before
        `</movie>` on line 40)" / "… before the end of the file"
      • "closing `</titel>` does not match the open `<title>` (line 27)"
      • "`<rating` missing `>`" / "closing `</rating` missing `>`"
      • "closing `</x>` without an opening tag"
      • "text after the root element `</movie>`"
      • info: "`&` not escaped (Kodi accepts it, Emby may not)"
    Comments, <?…?>, <!DOCTYPE …> and CDATA are skipped; quotes inside a tag
    are respected."""
    errors, infos = [], []
    n = len(content)
    starts = [0]
    for i, ch in enumerate(content):
        if ch == "\n":
            starts.append(i + 1)
    import bisect

    def lc(pos):
        ln = bisect.bisect_right(starts, pos)
        return ln, pos - starts[ln - 1] + 1

    def err(pos, msg):
        ln, col = lc(pos)
        errors.append({"line": ln, "col": col, "message": msg})

    stack = []                 # (name, pos)
    root_closed_at = None      # (name, pos) once the root element is closed
    after_root_reported = False
    amp_lines = set()
    i = 0
    while i < n:
        ch = content[i]
        if ch != "<":
            if ch == "&" and not _ENTITY_RE.match(content, i):
                ln, col = lc(i)
                if ln not in amp_lines:
                    amp_lines.add(ln)
                    infos.append({"line": ln, "col": col,
                                  "message": "`&` not escaped (Kodi accepts it, Emby may not)"})
            if (root_closed_at and not after_root_reported and not ch.isspace()):
                err(i, f"text after the root element `</{root_closed_at[0]}>`")
                after_root_reported = True
            i += 1
            continue
        # ── markup ────────────────────────────────────────────────────────────
        if content.startswith("<!--", i):
            j = content.find("-->", i + 4)
            i = n if j == -1 else j + 3
            continue
        if content.startswith("<![CDATA[", i):
            j = content.find("]]>", i + 9)
            i = n if j == -1 else j + 3
            continue
        if content.startswith("<?", i) or content.startswith("<!", i):
            j = content.find(">", i + 2)
            i = n if j == -1 else j + 1
            continue
        closing = content.startswith("</", i)
        k = i + (2 if closing else 1)
        m = _TAGNAME_RE.match(content, k)
        if not m:
            err(i, "`<` that does not start a tag (write `&lt;` in text)")
            i += 1
            continue
        name = m.group(0)
        # find the end of the tag, honouring quotes; stop at a '<' (missing '>')
        j, quote = m.end(), None
        while j < n:
            c = content[j]
            if quote:
                if c == quote:
                    quote = None
            elif c in "\"'":
                quote = c
            elif c == ">" or c == "<":
                break
            j += 1
        if j >= n or content[j] == "<":
            err(i, f"closing `</{name}` missing `>`" if closing else f"`<{name}` missing `>`")
            end = j                                  # recover: the tag ends here
            self_closing = False
        else:
            end = j + 1
            self_closing = (not closing) and content[j - 1] == "/"
        if root_closed_at and not after_root_reported:
            err(i, f"text after the root element `</{root_closed_at[0]}>`")
            after_root_reported = True
        if closing:
            if not stack:
                if not root_closed_at:
                    err(i, f"closing `</{name}>` without an opening tag")
            elif stack[-1][0] == name:
                stack.pop()
                if not stack:
                    root_closed_at = (name, i)
            elif any(s[0] == name for s in stack):
                cl_line = lc(i)[0]
                while stack and stack[-1][0] != name:
                    oname, opos = stack.pop()
                    err(opos, f"`<{oname}>` opened here is never closed "
                              f"(expected `</{oname}>` before `</{name}>` on line {cl_line})")
                stack.pop()
                if not stack:
                    root_closed_at = (name, i)
            else:                                    # most likely a typo of the open tag:
                oname, opos = stack.pop()            # report it once and treat it as its close
                err(i, f"closing `</{name}>` does not match the open `<{oname}>` (line {lc(opos)[0]})")
                if not stack:
                    root_closed_at = (oname, i)
        elif not self_closing:
            stack.append((name, i))
        i = end
    for oname, opos in reversed(stack):
        err(opos, f"`<{oname}>` opened here is never closed (expected `</{oname}>` before the end of the file)")
    errors.sort(key=lambda e: (e["line"], e["col"]))
    return errors, infos


def validate_xml_file(filepath, is_nfo=False, infos=None):     ### REWRITTEN v0.19.1 B12 ###
    """Validate XML/NFO structure.  Returns the list of error dicts
    {line, col, message} — ALL of them, with the exact line and the tag names
    (scan_xml_structure).  Python's parser stays a cross-check: a file the
    parser rejects is never "OK" (its error is added when the scanner found
    nothing), and a file the parser accepts gets no scanner errors (no false
    alarms).  *infos* (a list), when given, receives info-level notes
    (unescaped `&`), which never make the file an error."""
    errors = []
    if not os.path.isfile(filepath): return errors
    ### NEW v0.10.0 — fast pre-check before heavy parse ###
    ok, reason = _fast_precheck_xml(filepath)
    if not ok:
        return [{"line": 0, "col": 0, "message": reason}]
    content = _read_text(filepath)                             ### MODIFIED v0.18.3 ###
    if content is None:
        return [{"line":0,"col":0,"message":"Cannot read file"}]
    if not content.strip(): return [{"line":1,"col":0,"message":"File is empty"}]
    if is_nfo and _is_url_only_nfo(content): return errors
    if content.startswith('\ufeff'): content = content[1:]

    scan_errors, scan_infos = scan_xml_structure(content)
    if infos is not None:
        _nu = _not_utf8_note(filepath)                         ### NEW v0.19.2 B37 ###
        if _nu:
            infos.append(dict(_nu))
        infos.extend(scan_infos)

    # Strip & / &amp; for parse — do NOT report as error (KODI-safe)
    parse_content = re.sub(r'&(?!amp;|lt;|gt;|quot;|apos;|#)', '&amp;', content)
    parser_error = None
    try:
        ET.fromstring(parse_content)
    except ET.ParseError as e:
        line, col = e.position if hasattr(e, 'position') else (0, 0)
        if "undefined entity" not in str(e).lower():
            parser_error = {"line": line, "col": col, "message": f"XML parser: {e}"}

    if parser_error is None:
        return []                                  # the parser accepts it → no false alarms
    errors = scan_errors or [parser_error]
    return sorted(errors, key=lambda e: (e["line"], e["col"]))


def _parse_xml_to_dict(filepath):
    """
    Parse an XML/NFO file into a flat+nested dict for tag comparison.
    Returns {} on failure.
    """
    if not filepath or not os.path.isfile(filepath): return None
    return _parse_root(filepath)                               ### MODIFIED v0.18.3 ###

def _xpath_get(root, dotpath):
    """
    Get values from an ET Element using dot-separated path.
    Returns list of non-empty string values found.
    Returns [] if nothing found.
    """
    if root is None: return []
    parts = dotpath.split('.')
    def _recurse(el, remaining):
        if not remaining:
            txt = (el.text or "").strip()
            return [txt] if txt else []
        tag = remaining[0]
        results = []
        for child in el:
            if child.tag.lower() == tag.lower():
                results.extend(_recurse(child, remaining[1:]))
        return results
    return _recurse(root, parts)

def _norm_val(v):
    """Normalise a value for comparison: lowercase, strip spaces."""
    return str(v).strip().lower()

def _norm_numeric(v):
    """Extract numeric float from string, or None."""
    try:
        # Handle "5.1" channels → 6 mapping
        if str(v).strip() == "5.1": return 6.0
        if str(v).strip() == "7.1": return 8.0
        if str(v).strip() == "2.0": return 2.0
        return float(re.sub(r'[^\d.]', '', str(v)))
    except Exception: return None

def _vals_match(vals_a, vals_b, tol_pct=0):
    """
    Return True if any value in vals_a matches any value in vals_b.
    Numeric comparison uses tol_pct tolerance.
    Text comparison is case-insensitive.
    """
    if not vals_a or not vals_b: return True   # missing → skip check
    for a in vals_a:
        for b in vals_b:
            if tol_pct > 0:
                na = _norm_numeric(a); nb = _norm_numeric(b)
                if na is not None and nb is not None and nb != 0:
                    if abs(na - nb) / nb * 100 <= tol_pct:
                        return True
                    continue
            if _norm_val(a) == _norm_val(b):
                return True
    return False

def get_movie_year_from_files(nfo_path, xml_path):
    """Extract production year from NFO (<year>) or XML (<ProductionYear>)."""
    for filepath, tags in [(nfo_path, ['year']), (xml_path, ['ProductionYear'])]:
        if not filepath or not os.path.isfile(filepath):
            continue
        try:
            root = _parse_root(filepath)                       ### MODIFIED v0.18.3 ###
            if root is None:
                continue
            for tag in tags:
                el = root.find(tag)
                if el is not None:
                    txt = (el.text or "").strip()
                    if txt and re.match(r'^\d{4}$', txt):
                        return txt
        except Exception:
            pass
    return None


### NEW v0.10.0 — extract display movie name with fallback chain ###
def get_movie_name_from_files(nfo_path, xml_path, subfolder_name):
    """
    Return best movie name with fallback priority:
    1. NFO <title>
    2. XML <LocalTitle>
    3. NFO <originaltitle>
    4. XML <OriginalTitle>
    5. Folder name (subfolder_name)
    v0.10.2: HTML entities decoded via html.unescape()
    """
    def _tag(fp, tag):
        if not fp or not os.path.isfile(fp): return ""
        try:
            content = _read_text(fp) or ""                     ### MODIFIED v0.18.3 ###
            m = re.search(rf"<{tag}[^>]*>([^<]+)</{tag}>", content, re.IGNORECASE)
            if not m: return ""
            return html.unescape(m.group(1).strip())  # v0.10.2 — decode &amp; etc.
        except Exception: return ""
    for (fp, tag) in [
        (nfo_path, "title"),
        (xml_path, "LocalTitle"),
        (nfo_path, "originaltitle"),
        (xml_path, "OriginalTitle"),
    ]:
        v = _tag(fp, tag)
        if v: return v
    return subfolder_name


### NEW v0.10.0 — extract year with fallback ###
def get_movie_year_display(nfo_path, xml_path):
    """
    Return year string with fallback:
    1. NFO <year>
    2. XML <ProductionYear>
    3. "-"
    """
    def _tag(fp, tag):
        if not fp or not os.path.isfile(fp): return ""
        try:
            content = _read_text(fp) or ""                     ### MODIFIED v0.18.3 ###
            m = re.search(rf"<{tag}[^>]*>([^<]+)</{tag}>", content, re.IGNORECASE)
            v = m.group(1).strip() if m else ""
            return v if re.match(r"^\d{4}$", v) else ""
        except Exception: return ""
    for (fp, tag) in [(nfo_path, "year"), (xml_path, "ProductionYear")]:
        v = _tag(fp, tag)
        if v: return v
    return "-"


_KODI_RATINGS_RE = re.compile(r'<ratings\b[^>]*>(.*?)</ratings>', re.I | re.S)   ### NEW v0.18.4 ###
_KODI_RATING_RE  = re.compile(r'<rating\b([^>]*)>(.*?)</rating>', re.I | re.S)


def _kodi_ratings(content):                                    ### NEW v0.18.4 ###
    """
    Read the Kodi v17+ NFO format:
        <ratings><rating name="imdb" max="10" default="true">
            <value>7.3</value><votes>12345</votes></rating></ratings>
    Prefers the element marked default="true", then name="imdb", then the
    first one.  Returns (rating_float, votes_int_or_None) or (None, None).
    """
    m = _KODI_RATINGS_RE.search(content or "")
    if not m:
        return None, None
    best = None
    for attrs, body in _KODI_RATING_RE.findall(m.group(1)):
        v  = re.search(r'<value>\s*([^<]*?)\s*</value>', body, re.I)
        vt = re.search(r'<votes>\s*([^<]*?)\s*</votes>', body, re.I)
        if not v:
            continue
        try:
            val = float(v.group(1).replace(",", "."))
        except ValueError:
            continue
        digits = re.sub(r"[^\d]", "", vt.group(1)) if vt else ""
        votes  = int(digits) if digits else None
        name   = re.search(r'name\s*=\s*"([^"]*)"', attrs, re.I)
        score  = (2 if 'default="true"' in attrs.lower().replace(" ", "") else 0) + \
                 (1 if name and name.group(1).lower() == "imdb" else 0)
        if best is None or score > best[0]:
            best = (score, val, votes)
    return (best[1], best[2]) if best else (None, None)


def extract_rating_from_files(nfo_path, xml_path):              ### NEW v0.15.0 — adds votes + source ###
    """
    Extract movie rating and votes from NFO and/or XML files.

    Rating priority:  1. NFO <rating>   2. XML <IMDBrating>   3. XML <Rating>
    Votes priority:   1. NFO <votes>    2. XML <Votes>         3. XML <VoteCount>

    Returns
    -------
    (rating_str, status, rating_value, votes_int, votes_source_tag, rating_source_tag)
        rating_str       : display string e.g. "7.3" or "-"
        status           : STATUS_OK / STATUS_WARN / STATUS_ERROR / STATUS_MISSING
        rating_value     : float for sorting, -1.0 when absent/invalid
        votes_int        : int number of votes (0 if missing)
        votes_source_tag : string describing votes source e.g. "nfo_votes" / "xml_Votes" / "xml_VoteCount" / ""
        rating_source_tag: string describing rating source e.g. "nfo_rating" / "xml_IMDBrating" / "xml_Rating" / ""
    """
    def _try_float(s):
        try:
            return float(str(s).strip().replace(",", "."))
        except Exception:
            return None

    def _try_int(s):
        try:
            v = str(s).strip().replace(",", "").replace(".", "")
            return int(v)
        except Exception:
            return None

    nfo_val = None
    nfo_votes = None
    xml_imdb_val = None
    xml_rating_val = None
    xml_votes_val = None       # from <Votes>
    xml_votecount_val = None   # from <VoteCount>
    parse_error = False

    if nfo_path and os.path.isfile(nfo_path):
        try:
            content = _read_text(nfo_path) or ""              ### MODIFIED v0.18.3 ###
            m = re.search(r'<rating[^>]*>([^<]*)</rating>', content, re.IGNORECASE)
            if m:
                raw = m.group(1).strip()
                if raw:
                    val = _try_float(raw)
                    if val is not None:
                        nfo_val = val
                    else:
                        parse_error = True
            mv = re.search(r'<votes[^>]*>([^<]*)</votes>', content, re.IGNORECASE)
            if mv:
                raw_v = mv.group(1).strip()
                if raw_v:
                    iv = _try_int(raw_v)
                    if iv is not None:
                        nfo_votes = iv
            if nfo_val is None:                                  ### NEW v0.18.4 — Kodi v17+ block ###
                kv, kvotes = _kodi_ratings(content)
                if kv is not None:
                    nfo_val = kv
                    parse_error = False
                    if nfo_votes is None and kvotes is not None:
                        nfo_votes = kvotes
        except Exception:
            parse_error = True

    if xml_path and os.path.isfile(xml_path):
        try:
            content = _read_text(xml_path) or ""              ### MODIFIED v0.18.3 ###
            for tag in ["IMDBrating", "Rating"]:
                m = re.search(rf'<{tag}[^>]*>([^<]*)</{tag}>', content, re.IGNORECASE)
                if m:
                    raw = m.group(1).strip()
                    if raw:
                        val = _try_float(raw)
                        if val is not None:
                            if tag.lower() == "imdbrating":
                                xml_imdb_val = val
                            else:
                                if xml_rating_val is None:
                                    xml_rating_val = val
                        else:
                            parse_error = True
            # Votes from XML
            mv = re.search(r'<Votes[^>]*>([^<]*)</Votes>', content)
            if mv:
                raw_v = mv.group(1).strip()
                if raw_v:
                    iv = _try_int(raw_v)
                    if iv is not None:
                        xml_votes_val = iv
            mvc = re.search(r'<VoteCount[^>]*>([^<]*)</VoteCount>', content)
            if mvc:
                raw_v = mvc.group(1).strip()
                if raw_v:
                    iv = _try_int(raw_v)
                    if iv is not None:
                        xml_votecount_val = iv
        except Exception:
            parse_error = True

    if parse_error and nfo_val is None and xml_imdb_val is None and xml_rating_val is None:
        return "-", STATUS_ERROR, -1.0, 0, "", ""

    values = {}
    if nfo_val is not None:         values["nfo"] = nfo_val
    if xml_imdb_val is not None:    values["xml_imdb"] = xml_imdb_val
    if xml_rating_val is not None:  values["xml_rating"] = xml_rating_val

    if not values:
        return "-", STATUS_MISSING, -1.0, 0, "", ""

    # Determine primary rating and source
    if "nfo" in values:
        primary = values["nfo"]; rating_source = "nfo_rating"
    elif "xml_imdb" in values:
        primary = values["xml_imdb"]; rating_source = "xml_IMDBrating"
    else:
        primary = values["xml_rating"]; rating_source = "xml_Rating"

    all_vals = list(values.values())
    has_conflict = len(all_vals) > 1 and any(abs(v - all_vals[0]) > 0.05 for v in all_vals[1:])

    # Determine votes (priority: nfo_votes > xml_votes > xml_votecount)
    # Check for votes conflict
    existing_votes = {}
    if nfo_votes is not None:        existing_votes["nfo_votes"] = nfo_votes
    if xml_votes_val is not None:    existing_votes["xml_Votes"] = xml_votes_val
    if xml_votecount_val is not None: existing_votes["xml_VoteCount"] = xml_votecount_val

    votes_conflict = (len(existing_votes) > 1 and
                      len(set(existing_votes.values())) > 1)

    # Choose votes by priority
    if nfo_votes is not None:
        chosen_votes = nfo_votes; votes_source = "nfo_votes"
    elif xml_votes_val is not None:
        chosen_votes = xml_votes_val; votes_source = "xml_Votes"
    elif xml_votecount_val is not None:
        chosen_votes = xml_votecount_val; votes_source = "xml_VoteCount"
    else:
        chosen_votes = 0; votes_source = ""

    # v0.16.0: Rating status reflects ONLY rating conflict — votes conflict moved to Votes column
    status = STATUS_WARN if has_conflict else STATUS_OK  ### NEW v0.16.0 ###

    rating_str = f"{primary:.1f}"
    return rating_str, status, primary, chosen_votes, votes_source, rating_source


def extract_votes_from_files(nfo_path, xml_path):          ### NEW v0.16.0 ###
    """
    Extract vote count from NFO and XML with conflict detection.
    Priority: 1) NFO <votes>   2) XML <Votes>   3) XML <VoteCount>
    Conflict checked only between NFO <votes> and XML <Votes>.
    Returns (votes_int, status, source_tag).
    """
    def _parse_votes(s):
        try:
            v = re.sub(r'[^\d]', '', str(s).strip())
            return int(v) if v else None
        except Exception:
            return None

    nfo_votes = None
    xml_votes = None
    xml_votecount = None
    parse_error = False

    if nfo_path and os.path.isfile(nfo_path):
        try:
            content = _read_text(nfo_path) or ""              ### MODIFIED v0.18.3 ###
            m = re.search(r'<votes[^>]*>([^<]*)</votes>', content, re.IGNORECASE)
            if m:
                raw = m.group(1).strip()
                if raw:
                    iv = _parse_votes(raw)
                    if iv is not None: nfo_votes = iv
                    else: parse_error = True
            if nfo_votes is None:                                ### NEW v0.18.4 — Kodi v17+ block ###
                _kv, kvotes = _kodi_ratings(content)
                if kvotes is not None:
                    nfo_votes = kvotes
                    parse_error = False
        except Exception:
            parse_error = True

    if xml_path and os.path.isfile(xml_path):
        try:
            content = _read_text(xml_path) or ""              ### MODIFIED v0.18.3 ###
            mv = re.search(r'<Votes[^>]*>([^<]*)</Votes>', content)
            if mv:
                raw = mv.group(1).strip()
                if raw:
                    iv = _parse_votes(raw)
                    if iv is not None: xml_votes = iv
                    else: parse_error = True
            mvc = re.search(r'<VoteCount[^>]*>([^<]*)</VoteCount>', content)
            if mvc:
                raw = mvc.group(1).strip()
                if raw:
                    iv = _parse_votes(raw)
                    if iv is not None: xml_votecount = iv
                    else: parse_error = True
        except Exception:
            parse_error = True

    conflict = (nfo_votes is not None and xml_votes is not None
                and nfo_votes != xml_votes)

    if nfo_votes is not None:
        chosen = nfo_votes; src = "nfo_votes"
    elif xml_votes is not None:
        chosen = xml_votes; src = "xml_Votes"
    elif xml_votecount is not None:
        chosen = xml_votecount; src = "xml_VoteCount"
    else:
        chosen = 0; src = ""

    if parse_error and chosen == 0:
        return 0, STATUS_ERROR, ""
    if chosen == 0 and not parse_error:
        return 0, STATUS_MISSING, ""
    if conflict:
        return chosen, STATUS_WARN, src
    return chosen, STATUS_OK, src


def extract_source_ids_from_files(nfo_path, xml_path):     ### NEW v0.16.0 ###
    """
    Extract IMDB and TMDB IDs from all 12 authoritative tags.

    XML: IMDB → <IMDB>, <IMDbId>, <IMDB_ID>
         TMDB → <TMDB>, <TMDbId>, <TMDB_ID>
    NFO: IMDB → <id>, <imdbid>, <id moviedb="imdb">
         TMDB → <tmdbid>, <id moviedb="tmdb">, <id moviedb="themoviedb">

    Icon per source:
        STATUS_OK      all found tags agree
        STATUS_WARN    tags disagree or some missing but at least one valid
        STATUS_MISSING none found
        STATUS_ERROR   any tag present but unreadable

    Returns dict: imdb_val, imdb_status, imdb_all_vals,
                  tmdb_val, tmdb_status, tmdb_all_vals
    """
    imdb_xml = []; tmdb_xml = []
    imdb_nfo = []; tmdb_nfo = []
    imdb_error = False; tmdb_error = False
    # ### NEW v0.19.1 B13 ### an EMPTY tag is tracked apart from a parse error:
    # all tags of a source empty → MISSING ("empty tags ready to fill"); some
    # filled + some empty → ERROR as before.
    imdb_empty = False; tmdb_empty = False

    # ── XML ──────────────────────────────────────────────────────────────────
    if xml_path and os.path.isfile(xml_path):
        try:
            root = _parse_root(xml_path)                       ### MODIFIED v0.18.3 ###
            if root is None:
                raise ValueError("unparseable XML")
            for tag in ["IMDB", "IMDbId", "IMDB_ID"]:
                el = root.find(tag)
                if el is not None:
                    txt = (el.text or "").strip()
                    if txt: imdb_xml.append(txt)
                    else: imdb_empty = True                    ### MODIFIED v0.19.1 B13 ###
            for tag in ["TMDB", "TMDbId", "TMDB_ID"]:
                el = root.find(tag)
                if el is not None:
                    txt = (el.text or "").strip()
                    if txt: tmdb_xml.append(txt)
                    else: tmdb_empty = True                    ### MODIFIED v0.19.1 B13 ###
        except Exception:
            imdb_error = True; tmdb_error = True

    # ── NFO ──────────────────────────────────────────────────────────────────
    if nfo_path and os.path.isfile(nfo_path):
        try:
            root_nfo = _parse_root(nfo_path)                   ### MODIFIED v0.18.3 ###
            if root_nfo is None:
                raise ValueError("unparseable NFO")
            for el in root_nfo.findall("id"):
                mdb = el.get("moviedb", "")
                txt = (el.text or "").strip()
                if mdb.lower() == "imdb":
                    if txt: imdb_nfo.append(txt)
                    else: imdb_empty = True                    ### MODIFIED v0.19.1 B13 ###
                elif mdb.lower() in ("tmdb", "themoviedb"):
                    if txt: tmdb_nfo.append(txt)
                    else: tmdb_empty = True                    ### MODIFIED v0.19.1 B13 ###
                elif not mdb and txt.startswith("tt"):
                    imdb_nfo.append(txt)
            for el in root_nfo.findall("imdbid"):
                txt = (el.text or "").strip()
                if txt: imdb_nfo.append(txt)
                else: imdb_empty = True                        ### MODIFIED v0.19.1 B13 ###
            for el in root_nfo.findall("tmdbid"):
                txt = (el.text or "").strip()
                if txt: tmdb_nfo.append(txt)
                else: tmdb_empty = True                        ### MODIFIED v0.19.1 B13 ###
            # ### NEW v0.19.1 B19 ### Kodi v18+ <uniqueid type="imdb|tmdb" default="true">
            for el in root_nfo.findall("uniqueid"):
                typ = (el.get("type") or "").strip().lower()
                txt = (el.text or "").strip()
                if typ == "imdb":
                    if txt: imdb_nfo.append(txt)
                    else: imdb_empty = True
                elif typ in ("tmdb", "themoviedb"):
                    if txt: tmdb_nfo.append(txt)
                    else: tmdb_empty = True
        except Exception:
            # Malformed NFO — regex fallback
            try:
                content = _read_text(nfo_path) or ""           ### MODIFIED v0.18.3 ###
                m = re.search(r'<imdbid[^>]*>([^<]+)</imdbid>', content, re.IGNORECASE)
                if m: imdb_nfo.append(m.group(1).strip())
                m = re.search(r'<tmdbid[^>]*>([^<]+)</tmdbid>', content, re.IGNORECASE)
                if m: tmdb_nfo.append(m.group(1).strip())
                for m in re.finditer(
                        r'<id[^>]*moviedb=["\']?imdb["\']?[^>]*>([^<]+)</id>',
                        content, re.IGNORECASE):
                    imdb_nfo.append(m.group(1).strip())
                for m in re.finditer(
                        r'<id[^>]*moviedb=["\']?(?:tmdb|themoviedb)["\']?[^>]*>([^<]+)</id>',
                        content, re.IGNORECASE):
                    tmdb_nfo.append(m.group(1).strip())
                for m in re.finditer(                          ### NEW v0.19.1 B19 ###
                        r'<uniqueid[^>]*type=["\']?(imdb|tmdb|themoviedb)["\']?[^>]*>([^<]+)</uniqueid>',
                        content, re.IGNORECASE):
                    (imdb_nfo if m.group(1).lower() == "imdb" else tmdb_nfo).append(m.group(2).strip())
            except Exception:
                imdb_error = True; tmdb_error = True

    def _dedup(lst):
        seen = set(); out = []
        for v in lst:
            if v and v not in seen: seen.add(v); out.append(v)
        return out

    imdb_all = _dedup(imdb_xml + imdb_nfo)
    tmdb_all = _dedup(tmdb_xml + tmdb_nfo)

    # ── Classify IMDB ─────────────────────────────────────────────────────────
    # STATUS_WARN when:
    #   (a) values found but they disagree, OR
    #   (b) value found in one source but the other source file exists and has no tag
    #       (i.e. present in XML but absent in NFO, or vice-versa)         ### FIX v0.16.0 ###
    imdb_partial = (
        (bool(imdb_xml) and not imdb_nfo and nfo_path and os.path.isfile(nfo_path)) or
        (bool(imdb_nfo) and not imdb_xml and xml_path and os.path.isfile(xml_path))
    )

    if imdb_error or (imdb_empty and imdb_all):                ### MODIFIED v0.19.1 B13 ###
        imdb_val    = imdb_all[0] if imdb_all else None
        imdb_status = STATUS_ERROR
    elif not imdb_all:
        imdb_val    = None
        imdb_status = STATUS_MISSING
    elif len(set(imdb_all)) > 1 or imdb_partial:   ### FIX v0.16.0 — partial triggers WARN ###
        imdb_val    = imdb_all[0]
        imdb_status = STATUS_WARN
    else:
        imdb_val    = imdb_all[0]
        imdb_status = STATUS_OK

    # ── Classify TMDB ─────────────────────────────────────────────────────────
    tmdb_partial = (
        (bool(tmdb_xml) and not tmdb_nfo and nfo_path and os.path.isfile(nfo_path)) or
        (bool(tmdb_nfo) and not tmdb_xml and xml_path and os.path.isfile(xml_path))
    )

    if tmdb_error or (tmdb_empty and tmdb_all):                ### MODIFIED v0.19.1 B13 ###
        tmdb_val    = tmdb_all[0] if tmdb_all else None
        tmdb_status = STATUS_ERROR
    elif not tmdb_all:
        tmdb_val    = None
        tmdb_status = STATUS_MISSING
    elif len(set(tmdb_all)) > 1 or tmdb_partial:   ### FIX v0.16.0 — partial triggers WARN ###
        tmdb_val    = tmdb_all[0]
        tmdb_status = STATUS_WARN
    else:
        tmdb_val    = tmdb_all[0]
        tmdb_status = STATUS_OK

    return {
        "imdb_val": imdb_val, "imdb_status": imdb_status, "imdb_all_vals": imdb_all,
        "tmdb_val": tmdb_val, "tmdb_status": tmdb_status, "tmdb_all_vals": tmdb_all,
        # ### NEW v0.19.1 B13 ### True = the source has tags, all of them empty
        "imdb_empty_tags": bool(imdb_empty and not imdb_all and not imdb_error),
        "tmdb_empty_tags": bool(tmdb_empty and not tmdb_all and not tmdb_error),
    }



def build_opensubtitles_url(title, year=None):
    """Build an OpenSubtitles search URL from title and optional year."""
    if not title:
        return None
    safe_title = re.sub(r'[^\w\s\-]', '', title)
    safe_title = re.sub(r'\s+', '-', safe_title.strip())
    safe_title = re.sub(r'-+', '-', safe_title)
    if year:
        return (f"https://www.opensubtitles.org/en/search2/sublanguageid-all"
                f"/moviename-{safe_title}/movieyear-{year}")
    return (f"https://www.opensubtitles.org/en/search2/sublanguageid-all"
            f"/moviename-{safe_title}")


# ══════════════════════════════════════════════════════════════════════════════
# Phase 3 — Fallback XML parser (item 15)
# ══════════════════════════════════════════════════════════════════════════════

def _regex_extract_tag(content, tag, default=""):
    """Extract first occurrence of <tag>value</tag> case-insensitively."""
    m = re.search(rf'<{tag}[^>]*>([^<]*)</{tag}>', content, re.IGNORECASE)
    return m.group(1).strip() if m else default

def _regex_extract_all_tags(content, tag):
    """Extract all occurrences of <tag>value</tag>."""
    return [m.group(1).strip()
            for m in re.finditer(rf'<{tag}[^>]*>([^<]*)</{tag}>', content, re.IGNORECASE)
            if m.group(1).strip()]

def _safe_parse_xml(filepath):
    """
    Try ET.fromstring first; on failure fall back to regex extraction.
    Returns (root_or_None, fallback_dict).
    fallback_dict is populated when ET fails; root is None in that case.
    """
    if not filepath or not os.path.isfile(filepath):
        return None, {}
    content = _read_text(filepath)                             ### MODIFIED v0.18.3 ###
    if content is None:
        return None, {}
    root = _parse_root(filepath)
    if root is not None:
        return root, {}

    # Fallback: regex extraction of the most important tags
    fb = {
        "imdbid":   _regex_extract_tag(content, "imdbid") or
                    _regex_extract_tag(content, "IMDB_ID") or
                    _regex_extract_tag(content, "IMDB"),
        "tmdbid":   _regex_extract_tag(content, "tmdbid") or
                    _regex_extract_tag(content, "TMDbId") or
                    _regex_extract_tag(content, "TMDB"),
        "title":    _regex_extract_tag(content, "title") or
                    _regex_extract_tag(content, "LocalTitle"),
        "year":     _regex_extract_tag(content, "year") or
                    _regex_extract_tag(content, "ProductionYear"),
        "rating":   _regex_extract_tag(content, "rating") or
                    _regex_extract_tag(content, "IMDBrating") or
                    _regex_extract_tag(content, "Rating"),
        "votes":    _regex_extract_tag(content, "votes") or
                    _regex_extract_tag(content, "Votes") or
                    _regex_extract_tag(content, "VoteCount"),
        "language": _regex_extract_tag(content, "language") or
                    _regex_extract_tag(content, "Language"),
        "genres":   _regex_extract_all_tags(content, "genre"),
    }
    return None, fb


def get_movie_ids_robust(nfo_path, xml_path):
    """
    Extract IMDb and TMDb IDs from NFO and/or XML, with fallback parser.
    Returns (imdb_id, tmdb_id) — first non-empty value wins.
    """
    imdb_id = tmdb_id = None

    for filepath, is_nfo in [(nfo_path, True), (xml_path, False)]:
        if not filepath or not os.path.isfile(filepath):
            continue
        root, fb = _safe_parse_xml(filepath)

        if root is not None:
            if is_nfo:
                # ### NEW v0.19.1 B19 ### Kodi <uniqueid type=…> first — Kodi uses it first
                _uids = sorted(root.findall('uniqueid'),
                               key=lambda e: (e.get('default', '').lower() != 'true'))
                for el in _uids:
                    v = (el.text or "").strip()
                    typ = (el.get('type') or '').strip().lower()
                    if v and typ == 'imdb':
                        imdb_id = imdb_id or v
                    elif v and typ in ('tmdb', 'themoviedb'):
                        tmdb_id = tmdb_id or v
                # NFO: <imdbid>, <id moviedb="imdb">, <id>tt…</id>
                for tag in ['imdbid']:
                    el = root.find(tag)
                    if el is not None and el.text and el.text.strip():
                        imdb_id = imdb_id or el.text.strip()
                for el in root.iter('id'):
                    v = (el.text or "").strip()
                    mdb = el.get('moviedb', '')
                    if mdb.lower() == 'imdb' and v:
                        imdb_id = imdb_id or v
                    elif mdb.lower() in ('tmdb', 'themoviedb') and v:
                        tmdb_id = tmdb_id or v
                    elif not mdb and v.startswith('tt'):
                        imdb_id = imdb_id or v
                for tag in ['tmdbid']:
                    el = root.find(tag)
                    if el is not None and el.text and el.text.strip():
                        tmdb_id = tmdb_id or el.text.strip()
            else:
                # XML
                for tag in ['IMDB', 'IMDbId', 'IMDB_ID']:
                    el = root.find(tag)
                    if el is not None and el.text and el.text.strip():
                        imdb_id = imdb_id or el.text.strip(); break
                for tag in ['TMDbId', 'TMDB', 'TMDB_ID']:
                    el = root.find(tag)
                    if el is not None and el.text and el.text.strip():
                        tmdb_id = tmdb_id or el.text.strip(); break
        else:
            imdb_id = imdb_id or fb.get("imdbid") or None
            tmdb_id = tmdb_id or fb.get("tmdbid") or None

    return imdb_id, tmdb_id


