def scan_one_subfolder(sub_path, sub_name, use_ffprobe=None, force_ffprobe=False):
    """Full scan of a single subfolder. Returns result dict.
    force_ffprobe=True runs FFprobe regardless of the global use_ffprobe setting.
    ### MODIFIED v0.18.4 — one directory listing per movie (_FolderListing) ###
    """
    if force_ffprobe:
        use_ffprobe = True
    elif use_ffprobe is None:
        use_ffprobe = SETTINGS.get("use_ffprobe", True)

    lst = _FolderListing(sub_path)
    if force_ffprobe:                                           ### NEW v0.19.1 I5 — Update (with FFprobe): fresh probe ###
        _vf = scan_video_files(sub_path, listing=lst).get("video_path")
        if _vf:
            _probe_json(_vf, True, force=True)
    _art = _artwork_row_fields(lst)                             ### MODIFIED v0.19.1 B23 — Kodi names ###
    _img_fields = _art["fields"]

    bc, bp, bc_avg_bytes = count_backdrops(sub_path, listing=lst)

    nfo_path, ne, nfo_name, nfo_kodi = resolve_nfo(lst, sub_name, _art["vb"])   ### MODIFIED v0.19.1 B23 ###
    nb  = lst.size(nfo_name) if ne else 0
    ninfo = []; xinfo = []                                     ### NEW v0.19.1 B12 — info notes (unescaped &) ###
    nerr = validate_xml_file(nfo_path, is_nfo=True, infos=ninfo) if ne else []

    xml_path = lst.path_of("movie.xml")
    xe  = lst.has("movie.xml")
    xb  = lst.size("movie.xml")
    xerr = validate_xml_file(xml_path, is_nfo=False, infos=xinfo) if xe else []
    lang = extract_language_from_xml(xml_path) if xe else "—"

    ns = (STATUS_ERROR if nerr else STATUS_OK) if ne else STATUS_MISSING
    xs = (STATUS_ERROR if xerr else STATUS_OK) if xe else STATUS_MISSING

    vi = scan_video_files(sub_path, listing=lst)

    # ffprobe for resolution (if enabled)
    if use_ffprobe and vi["video_path"] and FFPROBE_PATH:
        w, h = _get_video_resolution(vi["video_path"], use_ffprobe=True)
        vi["video_width"]   = w
        vi["video_height"]  = h
        vi["video_quality"] = classify_quality(w, h)

    si = scan_subtitles(sub_path, vi["video_path"], use_ffprobe=use_ffprobe, listing=lst)
    audio_tracks = []
    if use_ffprobe and vi["video_path"] and FFPROBE_PATH:
        audio_tracks = scan_audio_tracks(vi["video_path"], use_ffprobe=True)

    iso = SETTINGS.get("lang_ok_code", "PT")
    subs_hard = get_hardsub_langs(nfo_path if ne else None, xml_path if xe else None)   ### NEW v0.19.1 B15 ###
    if subs_hard:
        si["subs_summary"] = _subs_summary(si["subs_internal"], si["subs_external"], vi["video_path"], subs_hard)
    lang_ok = compute_lang_ok(vi["video_path"], si["subs_internal"], si["subs_external"],
                               nfo_path if ne else None,
                               xml_path if xe else None,
                               iso_code=iso, use_ffprobe=use_ffprobe, subs_hard=subs_hard)

    vs = (STATUS_MISSING if vi["video_count"] == 0
          else STATUS_ERROR if vi["video_count"] > 1 else STATUS_OK)

    _gf = _genre_row_fields(nfo_path if ne else None, xml_path if xe else None)   ### MODIFIED v0.19.1 — NFO + XML ###
    genres, genre_display, genre_status = _gf["genres"], _gf["genre_display"], _gf["genre_status"]

    rating_str, rating_status, rating_value, rating_votes, rating_votes_src, rating_src = (
        extract_rating_from_files(nfo_path if ne else None, xml_path if xe else None))
    votes_int, votes_status, votes_src = extract_votes_from_files(
        nfo_path if ne else None, xml_path if xe else None)
    src_ids = extract_source_ids_from_files(
        nfo_path if ne else None, xml_path if xe else None)

    titles = get_movie_titles_from_files(
        nfo_path if ne else None, xml_path if xe else None)
    nfo_title, xml_localtitle = get_primary_titles(
        nfo_path if ne else None, xml_path if xe else None)
    movie_year_raw = get_movie_year_from_files(
        nfo_path if ne else None, xml_path if xe else None)
    movie_name = get_movie_name_from_files(
        nfo_path if ne else None, xml_path if xe else None, sub_name)
    movie_year = get_movie_year_display(
        nfo_path if ne else None, xml_path if xe else None)

    ffprobe_ran = bool(use_ffprobe and vi["video_path"] and FFPROBE_PATH)

    _row = {
        **naming_row_fields(lst, sub_name, _art["vb"]),         ### NEW v0.19.2 F5 ###
        "video_kinds": vi.get("video_kinds", {}), "video_group": vi.get("video_group"),
        "subfolder": sub_name, "subfolder_path": sub_path,
        "library_root": _norm_lib(os.path.dirname(sub_path)),  ### NEW v0.19.0, normpath v0.19.1 ###
        "movie_name": movie_name, "movie_year": movie_year,
        "movie_title_raw": titles,
        "movie_year_raw": movie_year_raw,
        "nfo_title": nfo_title, "xml_localtitle": xml_localtitle,
        "scan_mtime": lst.newest_mtime(),
        **_img_fields,                                          ### MODIFIED v0.19.0 ###
        "backdrop_count": bc, "backdrop_paths": bp, "backdrop_avg_bytes": bc_avg_bytes,
        "nfo_exists": ne, "nfo_path": nfo_path,
        "nfo_kodi_name": nfo_kodi,                             ### NEW v0.19.1 B23 ###
        "nfo_bytes": nb, "nfo_size": format_size(nb) if ne else "—",
        "nfo_status": ns, "nfo_errors": nerr, "nfo_infos": ninfo,   ### v0.19.1 B12 ###
        "xml_exists": xe, "xml_path": xml_path,
        "xml_bytes": xb, "xml_size": format_size(xb) if xe else "—",
        "xml_status": xs, "xml_errors": xerr, "xml_infos": xinfo,   ### v0.19.1 B12 ###
        "language": lang,
        "video_count": vi["video_count"], "video_files": vi["video_files"],
        "video_ext": vi["video_ext"], "video_path": vi["video_path"],
        "video_bytes": vi["video_bytes"], "video_size": vi["video_size"],
        "video_width": vi["video_width"], "video_height": vi["video_height"],
        "video_quality": vi["video_quality"], "video_status": vs,
        "subs_internal": si["subs_internal"], "subs_external": si["subs_external"],
        "subs_summary": si["subs_summary"],
        "subs_hard": subs_hard,                                ### NEW v0.19.1 B15 ###
        "audio_tracks": audio_tracks,
        "ffprobe_ran": ffprobe_ran,
        "lang_ok": lang_ok,
        "genres": genres, "genre_display": genre_display, "genre_status": genre_status,
        "genre_source": _gf["genre_source"], "genre_only_in_xml": _gf["genre_only_in_xml"],   ### NEW v0.19.1 ###
        "genre_only_in_nfo": _gf["genre_only_in_nfo"], "genre_nfo_wrong_tags": _gf["genre_nfo_wrong_tags"],
        "rating_str": rating_str, "rating_status": rating_status,
        "rating_value": rating_value,
        "rating_votes": rating_votes, "rating_votes_src": rating_votes_src,
        "rating_src": rating_src,
        "votes_int": votes_int, "votes_status": votes_status,
        "votes_src": votes_src,
        "source_imdb_val": src_ids["imdb_val"],
        "source_imdb_status": src_ids["imdb_status"],
        "source_imdb_all": src_ids["imdb_all_vals"],
        "source_tmdb_val": src_ids["tmdb_val"],
        "source_tmdb_status": src_ids["tmdb_status"],
        "source_tmdb_all": src_ids["tmdb_all_vals"],
        "source_imdb_empty": src_ids["imdb_empty_tags"],       ### NEW v0.19.1 B13 ###
        "source_tmdb_empty": src_ids["tmdb_empty_tags"],       ### NEW v0.19.1 B13 ###
        "duplicate_of": [],
    }
    _refill_audio_row(_row)                                    ### NEW v0.19.1 B16 ###
    _apply_health(_row)
    return _row

# ── JSON persistence helpers ───────────────────────────────────────────────────
def _results_from_json(data):
    defaults = {
        "video_width": None, "video_height": None, "video_quality": "—",
        "lang_ok": "—", "pt_ok": "—", "backdrop_paths": [],
        "backdrop_avg_bytes": 0,  ### NEW v0.15.0 ###
        "folder_exists": False, "folder_path": "", "folder_bytes": 0,
        "folder_size": "—", "folder_dim": None, "folder_corrupt": False,
        "folder_desc": "", "poster_desc": "", "fanart_desc": "",
        "poster_status": STATUS_MISSING, "fanart_status": STATUS_MISSING,
        "folder_status": STATUS_MISSING,
        "genres": [], "genre_display": "—", "genre_status": STATUS_ERROR,
        "movie_name": "", "movie_year": "-",
        # v0.11.0 — image quality tiers                      ### NEW v0.11.0 ###
        "poster_quality": "—", "folder_quality": "—", "fanart_quality": "—",
        # v0.12.0 — rating                                   ### NEW v0.12.0 ###
        "rating_str": "-", "rating_status": STATUS_MISSING, "rating_value": -1.0,
        "rating_votes": 0, "rating_votes_src": "", "rating_src": "",   ### NEW v0.15.0 ###
        "audio_tracks": [],                                              ### FIX v0.15.0 ###
        # v0.16.0 — votes and source                         ### NEW v0.16.0 ###
        "votes_int": 0, "votes_status": STATUS_MISSING, "votes_src": "",
        "source_imdb_val": None, "source_imdb_status": STATUS_MISSING, "source_imdb_all": [],
        "source_tmdb_val": None, "source_tmdb_status": STATUS_MISSING, "source_tmdb_all": [],
        # v0.18.2 — health engine fields                     ### ADDED_BY_CLAUDE_v18.2 ###
        "health_status": "warning", "health_reasons": [],
        "movie_title_raw": [], "movie_year_raw": None, "ffprobe_ran": False,
        # v0.18.3                                                ### NEW v0.18.3 ###
        "nfo_title": "", "xml_localtitle": "", "scan_mtime": None,
        # v0.18.4                                                ### NEW v0.18.4 ###
        "health_errors": [], "health_warnings": [], "duplicate_of": [],
        # v0.19.0 — image facts (None = not probed by this version) ### NEW v0.19.0 ###
        "poster_format": None, "poster_decode_ok": None, "poster_mismatch": False, "poster_flags": {},
        "folder_format": None, "folder_decode_ok": None, "folder_mismatch": False, "folder_flags": {},
        "fanart_format": None, "fanart_decode_ok": None, "fanart_mismatch": False, "fanart_flags": {},
        "id_check": None,                                       ### NEW v0.19.0 ###
        "genre_source": "", "genre_only_in_xml": False,          ### NEW v0.19.1 ###
        "genre_only_in_nfo": False, "genre_nfo_wrong_tags": False,
    }
    # ### NEW v0.19.2 B27 ### — every other key a fresh scan row has, with the
    # "nothing found" values of the scan's stub row, so a row cached by an older
    # version (or the self-test's legacy "OldRow") never raises KeyError in the
    # table / stats code (it showed as "KeyError: 'poster_exists'" in a Tk callback).
    for _k in ("poster", "fanart"):
        defaults.update({f"{_k}_exists": False, f"{_k}_path": "", f"{_k}_bytes": 0, f"{_k}_size": "—",
                         f"{_k}_dim": None, f"{_k}_corrupt": False, f"{_k}_style": "plain", f"{_k}_tried": []})
    defaults.update({"folder_style": "plain", "folder_tried": [], "art_style": "plain", "backdrop_count": 0})
    for _k in ("nfo", "xml"):
        defaults.update({f"{_k}_exists": False, f"{_k}_path": "", f"{_k}_bytes": 0, f"{_k}_size": "—",
                         f"{_k}_status": STATUS_MISSING, f"{_k}_errors": [], f"{_k}_infos": []})
    defaults.update({
        "nfo_kodi_name": True, "language": "—",
        "video_count": 0, "video_files": [], "video_ext": "—", "video_path": None,
        "video_bytes": 0, "video_size": "—", "video_status": STATUS_MISSING,
        "subs_external": [], "subs_internal": [], "subs_hard": [], "subs_summary": "None",
        "source_imdb_empty": False, "source_tmdb_empty": False,
        # v0.19.2 F5 — naming intelligence                    ### NEW v0.19.2 F5 ###
        "nfo_all": [], "nfo_all_differ": False, "xml_notes": [], "art_notes": [], "extra_art": [], "extra_dirs": [],
        "video_kinds": {}, "video_group": None,
        "poster_servers": None, "fanart_servers": None, "folder_servers": None,   # None = not known (no tooltip line)
    })
    _mutable = [k for k, v in defaults.items() if isinstance(v, (list, dict))]   ### NEW v0.19.2 B27 ###
    out = []
    for r in data:
        row = dict(defaults)
        row.update(r)
        for _k in _mutable:                                     ### NEW v0.19.2 B27 — no list shared between rows ###
            if _k not in r:
                row[_k] = type(defaults[_k])()
        # Migrate old pt_ok → lang_ok if needed
        if "pt_ok" in row and "lang_ok" not in row:
            row["lang_ok"] = row["pt_ok"]
        row["library_root"] = _norm_lib(row.get("library_root")             ### MODIFIED v0.19.1 — normpath ###
                                        or os.path.dirname(row.get("subfolder_path") or ""))
        out.append(row)
    return out

