# ══════════════════════════════════════════════════════════════════════════════
# Window size / position memory (v0.19.0)                      ### NEW v0.19.0 ###
# ══════════════════════════════════════════════════════════════════════════════
# SETTINGS["window_geometry"] = {window_id: {"geometry": "WxH+X+Y", "zoomed": bool}}
# One helper for the main window and every dialog: _remember_window(win, id).
# It is called AFTER the window's own sizing/centring code, so the saved
# position wins and centring is only the first-time default.  Non-resizable
# dialogs restore their position only.  <Configure> is debounced (400 ms) and
# only updates the in-memory setting; settings.json is written once when the
# window closes (through the normal _save_settings).  Restored geometry is
# clamped to the visible (virtual) screen so a removed monitor or a changed
# DPI never leaves a window off-screen.  Transient/grab behaviour untouched.

_GEOM_RE = re.compile(r"^(\d+)x(\d+)([+-]\d+)([+-]\d+)$")


def _virtual_screen(win):
    """(x, y, w, h) of the whole desktop: all monitors on Windows (ctypes),
    the Tk screen size elsewhere."""
    if os.name == "nt":
        try:
            import ctypes
            u = ctypes.windll.user32
            x, y, w, h = (u.GetSystemMetrics(76), u.GetSystemMetrics(77),
                          u.GetSystemMetrics(78), u.GetSystemMetrics(79))
            if w > 0 and h > 0:
                return x, y, w, h
        except Exception:
            pass
    try:
        return 0, 0, win.winfo_screenwidth(), win.winfo_screenheight()
    except Exception:
        return 0, 0, 1920, 1080


def _norm_lib(path):                                            ### NEW v0.19.1 ###
    """Windows-style library path (z:/film_kids → z:\\film_kids); '' stays ''."""
    path = (path or "").strip()
    return os.path.normpath(path) if path else ""


def _clamp_geometry(geom, win):
    """Return a 'WxH+X+Y' string guaranteed to be at least partly visible, or
    None when *geom* is not a geometry string."""
    m = _GEOM_RE.match(str(geom or "").strip())
    if not m:
        return None
    w, h, x, y = int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))
    vx, vy, vw, vh = _virtual_screen(win)
    w = max(100, min(w, vw))
    h = max(60,  min(h, vh))
    x = max(vx - w + 120, min(x, vx + vw - 120))     # >= 120 px of the title bar visible
    y = max(vy,           min(y, vy + vh - 60))
    return f"{w}x{h}{x:+d}{y:+d}"


def _remember_window(win, wid, resizable=True):
    """Restore the saved geometry of window *wid* and keep SETTINGS up to date.
    Call it last in the window's __init__ (after its own geometry/centring)."""
    try:
        store = SETTINGS.get("window_geometry")
        if not isinstance(store, dict):
            store = {}
            SETTINGS["window_geometry"] = store
        saved = store.get(wid)
        saved = saved if isinstance(saved, dict) else {}
        geom = _clamp_geometry(saved.get("geometry"), win)
        win.update_idletasks()
        if geom:
            if resizable:
                win.geometry(geom)
            else:                                   # position only
                gm = _GEOM_RE.match(geom)
                win.geometry(gm.group(3) + gm.group(4))
        if saved.get("zoomed") and resizable:
            win.state("zoomed")
    except Exception as ex:
        logger.debug(f"_remember_window restore ({wid}): {ex}")

    state = {"after": None}

    def _capture():
        state["after"] = None
        try:
            if not win.winfo_exists():
                return
            st = win.state()
        except Exception:
            return
        try:
            # look the store up every time: SETTINGS["window_geometry"] may have
            # been replaced since the window was created
            store = SETTINGS.get("window_geometry")
            if not isinstance(store, dict):
                store = {}
                SETTINGS["window_geometry"] = store
            if st == "zoomed":
                entry = dict(store.get(wid) or {})
                entry["zoomed"] = True          # keep the last normal geometry too
                store[wid] = entry
                return
            if st != "normal":
                return                          # iconic / withdrawn: nothing useful
            g = win.geometry()
            m = _GEOM_RE.match(g)
            if not m or int(m.group(1)) <= 1 or int(m.group(3)) <= -30000:
                return
            store[wid] = {"geometry": g, "zoomed": False}
        except Exception:
            pass

    def _on_configure(e):
        if e.widget is not win:
            return
        if state["after"] is not None:
            try:
                win.after_cancel(state["after"])
            except Exception:
                pass
        try:
            state["after"] = win.after(400, _capture)
        except Exception:
            state["after"] = None

    def _on_destroy(e):
        if e.widget is not win:
            return
        if state["after"] is not None:
            try:
                win.after_cancel(state["after"])
            except Exception:
                pass
            state["after"] = None
        _capture()
        try:
            _save_settings(SETTINGS)            # one write per window close
        except Exception:
            pass

    win.bind("<Configure>", _on_configure, add="+")
    win.bind("<Destroy>",   _on_destroy,   add="+")
    win._mc_geom_capture = _capture          # used by App._on_app_close
    return _capture


# SettingsDialog lives in settings_dialog.py, which must not import this module;
# it calls this hook (if present) at the end of its __init__.
SettingsDialog._remember_window_hook = staticmethod(_remember_window)   ### NEW v0.19.0 ###


class FrameExtractionDialog(tk.Toplevel):
    """Progress dialog for extracting backdrop frames — smooth animation."""

    def __init__(self, parent, video_path, sub_path, timeout_sec=60):
        super().__init__(parent)
        self.title("Extract Backdrop(s)…")
        self.geometry("540x360")
        self.configure(bg="#1e1e2e")
        self.transient(parent); self.grab_set()
        self.resizable(False, False)
        self.protocol("WM_DELETE_WINDOW", self._on_cancel)

        self._video_path  = video_path
        self._sub_path    = sub_path
        self._timeout_sec = timeout_sec
        self._cancelled   = False
        self._extracted   = []
        self._pct_target  = 0       # target for smooth animation
        self._pct_current = 0       # current animated value

        tk.Label(self, text="🎬  Extracting backdrop frames…",
                 font=("Helvetica", 12, "bold"), bg="#1e1e2e", fg="#cdd6f4"
                 ).pack(pady=(16, 2))
        tk.Label(self, text=os.path.basename(video_path),
                 font=("Consolas", 9), bg="#1e1e2e", fg="#6c7086").pack(pady=(0, 8))

        self.status_var = tk.StringVar(value="Preparing…")
        tk.Label(self, textvariable=self.status_var, font=("Helvetica", 10),
                 bg="#1e1e2e", fg="#a6adc8", wraplength=500).pack()

        self.eta_var = tk.StringVar(value="")
        tk.Label(self, textvariable=self.eta_var, font=("Helvetica", 9),
                 bg="#1e1e2e", fg="#6c7086").pack()
        self._ff_state = {}                                              ### NEW v0.19.2 B28 — spinner ###
        self._ff_label = tk.Label(self, text="", font=("Consolas", 9), bg="#1e1e2e", fg="#89b4fa")
        self._ff_label.pack()
        self._ff_spinner = _FFSpinner(self._ff_label, self._ff_state)

        pf = tk.Frame(self, bg="#1e1e2e"); pf.pack(fill="x", padx=30, pady=(8, 4))
        self.pbar_canvas = tk.Canvas(pf, height=24, bg="#313244",
                                     highlightthickness=0, relief="flat")
        self.pbar_canvas.pack(fill="x")
        self._draw_progress(0)

        # Controls row
        ctrl = tk.Frame(self, bg="#1e1e2e"); ctrl.pack(pady=(6, 0))

        # Backdrop count spinner (item 14)
        tk.Label(ctrl, text="Backdrops to extract:", font=("Helvetica", 9),
                 bg="#1e1e2e", fg="#a6adc8").pack(side="left", padx=(0, 4))
        self._count_var = tk.IntVar(value=SETTINGS.get("backdrop_count", 10))
        tk.Spinbox(ctrl, from_=1, to=50, textvariable=self._count_var,
                   width=4, font=("Helvetica", 9),
                   bg="#313244", fg="#cdd6f4", buttonbackground="#45475a",
                   relief="flat").pack(side="left", padx=(0, 18))

        tk.Label(ctrl, text="Per-frame timeout (s):", font=("Helvetica", 9),
                 bg="#1e1e2e", fg="#a6adc8").pack(side="left")
        self._timeout_var = tk.IntVar(value=timeout_sec)
        tk.Spinbox(ctrl, from_=10, to=300, textvariable=self._timeout_var,
                   width=5, font=("Helvetica", 9),
                   bg="#313244", fg="#cdd6f4", buttonbackground="#45475a",
                   relief="flat").pack(side="left", padx=(6, 0))

        tk.Button(self, text="  Cancel  ", font=("Helvetica", 10, "bold"),
                  bg="#f38ba8", fg="#1e1e2e", relief="flat", cursor="hand2",
                  command=self._on_cancel).pack(pady=(10, 16))

        self.after(150, self._start)
        self.after(50, self._animate_progress)
        _remember_window(self, "FrameExtractionDialog", resizable=False)   ### NEW v0.19.0 — window memory ###

    def _draw_progress(self, pct):
        c = self.pbar_canvas; c.delete("all")
        w = c.winfo_width() or 480; h = 24
        c.create_rectangle(0, 0, w, h, fill="#313244", outline="")
        fw = int(w * pct / 100)
        if fw > 0:
            c.create_rectangle(0, 0, fw, h, fill="#2d6e3f", outline="")
        c.create_text(w//2, h//2, text=f"{int(pct)}%",
                      fill="#cdd6f4", font=("Helvetica", 10, "bold"))

    def _animate_progress(self):
        """Smoothly animate progress bar at ~20fps."""
        if self._pct_current < self._pct_target:
            step = max(0.5, (self._pct_target - self._pct_current) * 0.15)
            self._pct_current = min(self._pct_target, self._pct_current + step)
            self._draw_progress(self._pct_current)
        try:
            self.after(50, self._animate_progress)
        except Exception:
            pass

    def _on_cancel(self):
        self._cancelled = True                                   # the runner kills FFmpeg within 0.2 s (v0.19.2 B28)
        self.status_var.set("Cancelling…")                       ### MODIFIED v0.19.2 B28 ###

    def _start(self):
        threading.Thread(target=self._worker, daemon=True).start()

    def _worker(self):
        video      = self._video_path
        sub        = self._sub_path
        t_limit    = max(10, self._timeout_var.get())
        n_frames   = max(1, min(50, self._count_var.get()))   # item 14: configurable count

        self.after(0, lambda: self.status_var.set("Reading video duration…"))
        _cancel = lambda: self._cancelled                       ### NEW v0.19.2 B28 — plain flag, no Tk ###
        _t_run = time.monotonic()
        self._ff_state.update(active=True, i=0, n=n_frames, t_frame=_t_run, t_run=_t_run)
        try:
            self._worker_frames(video, sub, t_limit, n_frames, _cancel)
        finally:
            self._ff_state["active"] = False

    def _worker_frames(self, video, sub, t_limit, n_frames, _cancel):   ### v0.19.2 B28 — body of _worker ###
        dur_result = get_video_duration(video, cancel=_cancel)  ### UPDATED v0.17.0; cancel v0.19.2 B28 ###
        if self._cancelled:
            self.after(0, self.destroy)
            return
        # get_video_duration now returns (float|None, estimated:bool)
        if isinstance(dur_result, tuple):
            duration, estimated = dur_result
        else:
            duration, estimated = dur_result, False            # legacy compatibility

        if not duration or duration <= 0:
            ext = os.path.splitext(video)[1].lower()
            if ext in (".mp4", ".mkv"):
                # Use a safe default estimate of 3600s and warn rather than abort
                duration  = 3600.0
                estimated = True
                self.after(0, lambda: self.status_var.set(
                    "⚠ FFprobe could not read duration — using 1-hour estimate."))
            else:
                self._finish_error("Cannot read video duration",
                    "FFprobe could not read the video length.\n\n"
                    "Possible causes:\n• Corrupt or incomplete file\n"
                    "• Unsupported container format\n"
                    "• File still being downloaded\n\n"
                    "Try playing the file in VLC to confirm it works.")
                return

        if estimated:
            self.after(0, lambda: self.status_var.set(
                "⚠ Duration estimated — extraction may start at wrong timestamp."))

        if duration < 20:
            self._finish_error("Video too short",
                f"Video is only {duration:.0f}s — need at least 20s for extraction.")
            return

        if duration < 120:
            start_sec = 2; end_sec = duration - 2
        elif duration < 600:
            start_sec = duration * 0.05; end_sec = duration * 0.95
        else:
            start_sec = 300; end_sec = duration - 300

        if end_sec <= start_sec:
            end_sec = duration * 0.9; start_sec = duration * 0.1

        divisor    = max(1, n_frames - 1) if n_frames > 1 else 1
        interval   = (end_sec - start_sec) / divisor if end_sec > start_sec else 1
        timestamps = [start_sec + i * interval for i in range(n_frames)]
        _new_paths = new_backdrop_paths(sub, n_frames)          ### MODIFIED v0.19.1 B23 — folder's naming style ###
        extracted  = []; failed = []
        frame_times = []
        timeouts = 0; slow_stop = False                          ### NEW v0.19.2 B28 — "slow file" breaker ###

        for i, ts in enumerate(timestamps):
            if self._cancelled: break
            if timeouts >= 2:
                slow_stop = True
                break
            self._ff_state.update(i=i + 1, t_frame=time.monotonic())   ### NEW v0.19.2 B28 ###
            out_p = _new_paths[i]                                ### MODIFIED v0.19.1 B23 ###
            fname = os.path.basename(out_p)
            mins  = int(ts // 60); secs_r = int(ts % 60)

            pct_per_frame = 100.0 / n_frames
            self._pct_target = int(i * pct_per_frame)

            self.after(0, lambda i=i, m=mins, s=secs_r, fn=fname, n=n_frames:
                       self.status_var.set(f"Frame {i+1}/{n}  at {m}:{s:02d}  →  {fn}"))

            t0 = time.time()
            ok, err_msg = extract_single_frame(video, ts, out_p, timeout_sec=t_limit, cancel=_cancel)   ### MODIFIED v0.19.2 B28 ###
            timeouts = (timeouts + 1) if (not ok and str(err_msg).startswith(_FF_TIMEOUT_TEXT)) else 0
            elapsed = time.time() - t0
            frame_times.append(elapsed)

            self._pct_target = int((i + 1) * pct_per_frame)

            if ok:
                extracted.append((fname, out_p))
            else:
                failed.append((i+1, f"{mins}:{secs_r:02d}", fname, err_msg))

            # ETA
            if frame_times:
                avg = sum(frame_times) / len(frame_times)
                remaining = avg * (n_frames - i - 1)
                if remaining > 60:
                    eta = f"ETA: {int(remaining//60)}m {int(remaining%60)}s"
                elif remaining > 0:
                    eta = f"ETA: {int(remaining)}s"
                else:
                    eta = "Almost done…"
                self.after(0, lambda e=eta: self.eta_var.set(e))

        self._extracted = [p for _, p in extracted]
        self._pct_target = 100

        if self._cancelled:
            for _, p in extracted:
                try: os.remove(p)
                except OSError: pass
            self.after(0, lambda: (
                self.status_var.set("Cancelled."),
                messagebox.showinfo("Cancelled",
                    "Extraction cancelled. Partial files removed.", parent=self),
                self.destroy()))
            return

        n_ok = len(extracted); n_bad = len(failed)
        if slow_stop:                                            ### NEW v0.19.2 B28 ###
            msg = B28_SLOW_TEXT.format(n=n_ok)
            logger.warning(f"Extract Backdrop(s) stopped (slow file): {video}")
            self.after(0, lambda: (messagebox.showwarning("Stopped", msg, parent=self), self.destroy()))
            return
        if n_bad == 0:
            ### UPDATED v0.18.0 — build file-range string correctly for all cases ###
            if n_ok == 1:
                only_fname = extracted[0][0]
                files_str = only_fname
            else:                                                ### MODIFIED v0.19.1 B23 — real names (Kodi or plain) ###
                files_str = f"{extracted[0][0]} → {extracted[-1][0]}"
            msg = (f"Done! All {n_frames} frame(s) extracted!\n\n"
                   f"Saved to: {sub}\n"
                   f"Files: {files_str}")
            self.after(0, lambda: (messagebox.showinfo("Done", msg, parent=self), self.destroy()))
        elif n_ok == 0:
            detail = "\n".join(f"  Frame {fi} at {ts}: {em}" for fi,ts,_,em in failed[:5])
            msg = (f"❌  No frames extracted.\n\nAll {n_frames} failed:\n{detail}\n\n"
                   "• Check the video codec is supported by your FFmpeg build\n"
                   "• Increase the per-frame timeout for large files\n"
                   "• Verify the file plays in VLC")
            self.after(0, lambda: (messagebox.showerror("Failed", msg, parent=self), self.destroy()))
        else:
            detail = "\n".join(f"  Frame {fi} at {ts}: {em}" for fi,ts,_,em in failed[:3])
            msg = (f"Partial: {n_ok}/{n_frames} frames saved.\n\nFailed ({n_bad}):\n{detail}\n\n"
                   "Saved frames are usable. Failed frames may be damaged sections.")
            self.after(0, lambda: (messagebox.showwarning("Partial", msg, parent=self), self.destroy()))

    def _finish_error(self, title, message):
        self.after(0, lambda: (messagebox.showerror(title, message, parent=self), self.destroy()))


class ImprovementsDialog(tk.Toplevel):
    """Pop-up showing improvement findings with copy/save options."""

    def __init__(self, parent, report_text, movie_count):
        super().__init__(parent)
        self.bind("<Escape>", lambda e: self.destroy())   ### NEW v0.19.2 B45 — Esc closes (nothing written) ###
        self.title(f"🔍  Improvements — {movie_count} movie(s)")
        self.geometry("780x560")
        self.configure(bg="#1e1e2e")
        self.transient(parent); self.grab_set()
        self.resizable(True, True)

        tk.Label(self, text="🔍  Improvement Findings",
                 font=("Helvetica", 13, "bold"), bg="#1e1e2e", fg="#f9e2af"
                 ).pack(anchor="w", padx=16, pady=(14, 2))

        fr = tk.Frame(self, bg="#1e1e2e")
        fr.pack(fill="both", expand=True, padx=16, pady=(4, 6))
        self._txt = t = tk.Text(fr, wrap="word", bg="#313244", fg="#cdd6f4",
                                font=("Consolas", 10), relief="flat", padx=10, pady=10)
        sb = ttk.Scrollbar(fr, orient="vertical", command=t.yview)
        t.configure(yscrollcommand=sb.set)
        t.pack(side="left", fill="both", expand=True)
        sb.pack(side="right", fill="y")

        # Colour tags
        t.tag_configure("h",      foreground="#89b4fa", font=("Consolas",10,"bold"))
        t.tag_configure("mv",     foreground="#a6e3a1", font=("Consolas",10,"bold"))
        t.tag_configure("mv_err", foreground="#f38ba8", font=("Consolas",10,"bold"))
        t.tag_configure("iss",    foreground="#f9e2af")
        t.tag_configure("err",    foreground="#f38ba8")   # scan errors in red
        t.tag_configure("ok",     foreground="#a6e3a1")
        t.tag_configure("sep",    foreground="#45475a")

        self._raw = report_text
        self._render(report_text)

        bf = tk.Frame(self, bg="#1e1e2e"); bf.pack(pady=(4, 12))
        tk.Button(bf, text="  📋 Copy to Clipboard  ",
                  font=("Helvetica", 10, "bold"),
                  bg="#89b4fa", fg="#1e1e2e", relief="flat", cursor="hand2",
                  command=self._copy).pack(side="left", padx=(0, 8))
        tk.Button(bf, text="  💾 Save to .txt  ",
                  font=("Helvetica", 10, "bold"),
                  bg="#a6e3a1", fg="#1e1e2e", relief="flat", cursor="hand2",
                  command=self._save).pack(side="left", padx=(0, 8))
        tk.Button(bf, text="  Close  ",
                  font=("Helvetica", 10, "bold"),
                  bg="#45475a", fg="#cdd6f4", relief="flat", cursor="hand2",
                  command=self.destroy).pack(side="left")
        _remember_window(self, "ImprovementsDialog", resizable=True)   ### NEW v0.19.0 — window memory ###

    def _render(self, text):
        t = self._txt
        t.configure(state="normal"); t.delete("1.0", "end")
        in_errors_section = False
        for line in text.splitlines():
            if "SCAN ERRORS" in line:
                in_errors_section = True
            if line.startswith("="):
                t.insert("end", line + "\n", "sep")
            elif line.startswith("─"):
                t.insert("end", line + "\n", "sep")
            elif line.startswith("📁"):
                tag = "mv_err" if in_errors_section else "mv"
                t.insert("end", line + "\n", tag)
            elif line.startswith("[OK]"):
                t.insert("end", line + "\n", "ok")
            elif in_errors_section and (line.strip().startswith("✖") or line.strip().startswith("•")):
                t.insert("end", line + "\n", "err")
            elif line.strip().startswith("•"):
                t.insert("end", line + "\n", "iss")
            elif line.startswith("Improvement Report") or line.startswith("Total") or line.startswith("SCAN ERRORS"):
                t.insert("end", line + "\n", "h")
            else:
                t.insert("end", line + "\n")
        t.configure(state="disabled")

    def _copy(self):
        self.clipboard_clear()
        self.clipboard_append(self._raw)
        messagebox.showinfo("Copied", "Report copied to clipboard.", parent=self)

    def _save(self):
        p = filedialog.asksaveasfilename(
            parent=self, title="Save Report",
            defaultextension=".txt",
            filetypes=[("Text files","*.txt"),("All","*.*")],
            initialfile="improvements_report.txt")
        if not p: return
        try:
            with open(p, "w", encoding="utf-8") as f:
                f.write(self._raw)
            messagebox.showinfo("Saved", f"Report saved to:\n{p}", parent=self)
        except Exception as e:
            messagebox.showerror("Save failed", str(e), parent=self)



# ── format_health_report — pure function (v0.18.2) ───────────────────────────
def _reason_key(reason):                                       ### NEW v0.18.4 ###
    """Collapse a health reason to its rule text (drop the movie-specific part)."""
    s = str(reason)
    for cut in (" (", ": "):
        i = s.find(cut)
        if i > 0:
            s = s[:i]
    return s.strip()


def format_library_statistics(results):                        ### NEW v0.18.4 ###
    """Library Statistics report (pure function, no Tk, no I/O)."""
    import datetime
    from collections import Counter
    n = len(results)
    sep = "=" * 60
    L = [f"Library Statistics \u2014 {n} movie(s)",
         f"Generated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}", sep, ""]
    if not n:
        return "\n".join(L + ["No movies loaded."])
    def _pct(k): return f"{k:5d}  ({k * 100 // n:3d}%)"
    hs = Counter(r.get("health_status", "warning") for r in results)
    roots = Counter((r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")) for r in results)   ### NEW v0.19.0 ###
    if roots:
        L += ["LIBRARIES"] + [f"  {_pct(c)}   {k}" for k, c in sorted(roots.items())] + [""]
    L += ["HEALTH",
          f"  OK       {_pct(hs.get('ok', 0))}",
          f"  Warning  {_pct(hs.get('warning', 0))}",
          f"  Error    {_pct(hs.get('error', 0))}", ""]
    total_bytes = sum(r.get("video_bytes", 0) or 0 for r in results)
    with_video  = sum(1 for r in results if r.get("video_count", 0) >= 1)
    L += ["VIDEO",
          f"  Movies with a video file   {_pct(with_video)}",
          f"  Total video size           {format_size(total_bytes)}",
          f"  Average video size         {format_size(total_bytes // max(with_video, 1))}"]
    vq = Counter(r.get("video_quality", "\u2014") for r in results)
    for q in sorted(vq, key=_quality_sort_key):
        L.append(f"    {q:12s} {_pct(vq[q])}")
    ac = Counter(t.get("language", "UND") for r in results for t in r.get("audio_tracks", []) or [])
    if ac:
        L.append("  Audio languages (tracks): " + ", ".join(f"{k} {v}" for k, v in ac.most_common(12)))
    L.append("")
    L += ["SUBTITLES / LANGUAGE",
          f"  Lang OK? = Y               {_pct(sum(1 for r in results if r.get('lang_ok') == 'Y'))}",
          f"  Lang OK? = N               {_pct(sum(1 for r in results if r.get('lang_ok') == 'N'))}",
          f"  External subtitle files    {_pct(sum(1 for r in results if r.get('subs_external')))}",
          f"  Embedded subtitle tracks   {_pct(sum(1 for r in results if r.get('subs_internal')))}"]
    xl = Counter((r.get("language") or "\u2014") for r in results)
    L.append("  XML <Language>: " + ", ".join(f"{k} {v}" for k, v in xl.most_common(10)))
    L.append("")
    L += ["ARTWORK"]
    for key, label in (("poster", "Poster"), ("folder", "Folder"), ("fanart", "Fanart")):
        present = sum(1 for r in results if r.get(f"{key}_exists"))
        qc = Counter(r.get(f"{key}_quality", "\u2014") for r in results if r.get(f"{key}_exists"))
        L.append(f"  {label:7s} present {_pct(present)}   " +
                 ", ".join(f"{q} {c}" for q, c in sorted(qc.items(), key=lambda kv: _poster_quality_sort_key(kv[0]) if key != 'fanart' else _fanart_quality_sort_key(kv[0]))))
    bcs = [r.get("backdrop_count", 0) for r in results]
    L.append(f"  Backdrops: total {sum(bcs)}, average {sum(bcs) / n:.1f} per movie, "
             f"{sum(1 for b in bcs if b == 0)} movie(s) without any")
    L.append("")
    L += ["METADATA",
          f"  NFO present                {_pct(sum(1 for r in results if r.get('nfo_exists')))}",
          f"  XML present                {_pct(sum(1 for r in results if r.get('xml_exists')))}",
          f"  IMDB ID present            {_pct(sum(1 for r in results if r.get('source_imdb_val')))}",
          f"  TMDB ID present            {_pct(sum(1 for r in results if r.get('source_tmdb_val')))}",
          f"  Rating present             {_pct(sum(1 for r in results if r.get('rating_status') not in (STATUS_MISSING, STATUS_ERROR)))}",
          f"  Duplicates flagged         {_pct(sum(1 for r in results if r.get('duplicate_of')))}", ""]
    gc = Counter(g for r in results for g in (r.get("genres") or []))
    L += ["GENRES (top 20)"]
    for g, c in gc.most_common(20):
        L.append(f"  {c:5d}  {g}")
    L.append("")
    dec = Counter()
    for r in results:
        y = str(r.get("movie_year", "-"))
        dec[(y[:3] + "0s") if y.isdigit() and len(y) == 4 else "unknown"] += 1
    L += ["DECADES"]
    for d, c in sorted(dec.items()):
        L.append(f"  {d:8s} {_pct(c)}")
    L.append("")
    rated = [r.get("rating_value") for r in results if (r.get("rating_value") or -1) >= 0]
    if rated:
        L.append(f"RATINGS   average {sum(rated) / len(rated):.2f} over {len(rated)} rated movie(s)")
    cnt = Counter(_reason_key(x) for r in results for x in r.get("health_reasons", []))
    if cnt:
        L += ["", "MOST COMMON HEALTH ISSUES"]
        for k, c in cnt.most_common(15):
            L.append(f"  {c:5d}  {k}")
    return "\n".join(L)


def format_duplicates_report(results):                         ### NEW v0.18.4 ###
    """Groups of movies that share an IMDB ID, a TMDB ID, or a title + year."""
    import datetime
    groups = _duplicate_groups(results)
    sep = "=" * 60
    L = [f"Duplicate Movies Report \u2014 {len(results)} movie(s) checked",
         f"Generated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}", sep, ""]
    if not groups:
        return "\n".join(L + ["No duplicates found."])
    L.append(f"{len(groups)} group(s) of possible duplicates:")
    L.append("")
    for why, rows in groups:
        L.append(f"\U0001f4c1  {why}")
        for r in rows:
            L.append(f"     {r.get('movie_name') or r.get('subfolder')}  [{r.get('movie_year', '-')}]  "
                     f"{r.get('video_quality', '—')}  {r.get('video_size', '—')}   \u2192  {r.get('subfolder_path', '')}")
        L.append("")
    return "\n".join(L)


def _norm_title_key(name):                                     ### NEW v0.18.4 ###
    import unicodedata
    s = unicodedata.normalize("NFKD", html.unescape(str(name or "")))
    s = "".join(c for c in s if not unicodedata.combining(c)).casefold()
    s = re.sub(r"[^\w\s]", " ", s)
    s = re.sub(r"\b(the|a|an|o|a|os|as|le|la|les|el|los|las|der|die|das)\b", " ", s)
    return " ".join(s.split())


def _duplicate_groups(results):                                ### NEW v0.18.4 ###
    """Return [(reason, [rows…]), …] for movies sharing an ID or title+year."""
    by_imdb, by_tmdb, by_title = {}, {}, {}
    for r in results:
        i = (r.get("source_imdb_val") or "").strip().lower()
        t = (r.get("source_tmdb_val") or "").strip()
        if i: by_imdb.setdefault(i, []).append(r)
        if t: by_tmdb.setdefault(t, []).append(r)
        k = _norm_title_key(r.get("movie_name") or r.get("subfolder"))
        y = str(r.get("movie_year", "-"))
        if k and y.isdigit():
            by_title.setdefault((k, y), []).append(r)
    groups, seen = [], set()
    for label, table in (("IMDB ID", by_imdb), ("TMDB ID", by_tmdb)):
        for key, rows in table.items():
            if len(rows) > 1:
                sig = frozenset(id(x) for x in rows)
                if sig not in seen:
                    seen.add(sig); groups.append((f"Same {label} {key}", rows))
    for (k, y), rows in by_title.items():
        if len(rows) > 1:
            sig = frozenset(id(x) for x in rows)
            if sig not in seen:
                seen.add(sig); groups.append((f"Same title and year: {rows[0].get('movie_name')} ({y})", rows))
    groups.sort(key=lambda g: (g[1][0].get("movie_name") or "").lower())
    return groups


def _detect_duplicates(results):                               ### NEW v0.18.4 ###
    """Set row['duplicate_of'] (names of the other folders) for every row."""
    for r in results:
        r["duplicate_of"] = []
    for _why, rows in _duplicate_groups(results):
        for r in rows:
            others = [x.get("subfolder", "?") for x in rows if x is not r]
            for o in others:
                if o not in r["duplicate_of"]:
                    r["duplicate_of"].append(o)
    return results


def _apply_health(row, rules=None, settings=None):             ### NEW v0.18.4 ###
    """Evaluate the rule engine for one row and store status, errors, warnings
    and the combined reasons list on the row.  Returns the status."""
    status, errs, warns = compute_movie_health_detailed(
        row, rules if rules is not None else SETTINGS.get("health_rules", {}),
        settings if settings is not None else SETTINGS)
    row["health_status"]   = status
    row["health_errors"]   = errs
    row["health_warnings"] = warns
    row["health_reasons"]  = errs + warns
    return status


def finalize_results(results):                                 ### NEW v0.18.4 ###
    """Duplicate detection + image re-evaluation + health for a whole result
    list (no I/O, fast).  ### MODIFIED v0.19.0 — image status re-derived from
    the cached facts so stale "corrupt" flags and old quality minimums never
    survive a load, a Recompute or a Save & Apply ###"""
    _detect_duplicates(results)
    rules = SETTINGS.get("health_rules", {})
    for r in results:
        try:
            reevaluate_row_images(r, SETTINGS)
            _apply_health(r, rules, SETTINGS)
        except Exception as e:
            logger.warning(f"finalize_results: {r.get('subfolder')}: {e}")
    return results


def format_health_report(results):                               ### ADDED_BY_CLAUDE_v18.2 ###
    """
    Build a human-readable health status report from a list of movie row dicts.
    Reads health_status / health_reasons — does NOT recompute health.
    Pure function: no Tk calls, no I/O.
    """
    import datetime
    from collections import Counter
    errors   = [r for r in results if r.get("health_status") == "error"]
    warnings = [r for r in results if r.get("health_status") == "warning"]
    ok_count = len(results) - len(errors) - len(warnings)
    total_issues = sum(len(r.get("health_reasons", [])) for r in results)
    affected = len(errors) + len(warnings)
    sep  = "=" * 60
    dash = "\u2500" * 48
    lines = [
        f"Health Status Report \u2014 {len(results)} movie(s) checked",
        f"Generated: {datetime.datetime.now().strftime('%Y-%m-%d %H:%M')}",
        sep, "",
        (f"\u26a0  WARNING movies: {len(warnings)}"
         f"    \u2715  ERROR movies: {len(errors)}"
         f"    \u2713  OK movies: {ok_count}"),
        "",
    ]
    # Most common issues (v0.18.4)
    counter = Counter(_reason_key(x) for r in results for x in r.get("health_reasons", []))
    if counter:
        lines.append("Most common issues:")
        for key, n in counter.most_common(15):
            lines.append(f"  {n:5d}  {key}")
        lines.append("")
    lines += [sep, ""]
    def _display_name(r):
        return r.get("movie_name") or r.get("subfolder", "Unknown")
    _roots = {(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")) for r in results}   ### NEW v0.19.0 ###
    def _lib_line(r):
        return [f"  Library: {r.get('library_root') or os.path.dirname(r.get('subfolder_path') or '')}"] if len(_roots) > 1 else []
    def _split(r):
        """(errors, warnings) — rows from older caches only have health_reasons."""
        e, w = r.get("health_errors"), r.get("health_warnings")
        if e is None and w is None:
            rs = r.get("health_reasons", [])
            return (rs, []) if r.get("health_status") == "error" else ([], rs)
        return (e or []), (w or [])
    for r in sorted(errors, key=_display_name):
        name = _display_name(r); year = r.get("movie_year", "-")
        lines.append(f"\U0001f4c1  {name}  [{year}]               [ERROR]")
        lines.extend(_lib_line(r))                                ### NEW v0.19.0 ###
        lines.append(dash)
        e, w = _split(r)
        for reason in e:
            lines.append(f"  \u2715  {reason}")
        for reason in w:                     # v0.18.4 — warnings of red movies are listed too
            lines.append(f"  \u26a0  {reason}")
        lines.append("")
    for r in sorted(warnings, key=_display_name):
        name = _display_name(r); year = r.get("movie_year", "-")
        lines.append(f"\U0001f4c1  {name}  [{year}]               [WARNING]")
        lines.extend(_lib_line(r))                                ### NEW v0.19.0 ###
        lines.append(dash)
        for reason in r.get("health_reasons", []):
            lines.append(f"  \u26a0  {reason}")
        lines.append("")
    lines += [
        sep,
        f"Total issues: {total_issues} across {affected} movie(s)",
        f"{ok_count} movie(s) have no health issues.",
    ]
    return "\n".join(lines)


