# Tooltip
# ══════════════════════════════════════════════════════════════════════════════

class TreeviewTooltip:
    def __init__(self, tree, fn):
        self.tree = tree; self.fn = fn; self.tw = None; self._lc = (None, None)
        tree.bind("<Motion>", self._m); tree.bind("<Leave>", self._h)

    def _m(self, e):
        i = self.tree.identify_row(e.y); c = self.tree.identify_column(e.x)
        if not i or not c: self._h(); return
        if (i, c) == self._lc: return
        self._lc = (i, c); t = self.fn(i, int(c.lstrip("#")) - 1)
        if t: self._s(e, t)
        else: self._h()

    def _s(self, e, t):
        self._h()
        self.tw = w = tk.Toplevel(self.tree); w.wm_overrideredirect(True)
        w.wm_geometry(f"+{e.x_root+16}+{e.y_root+10}"); w.configure(bg="#45475a")
        tk.Label(w, text=t, bg="#45475a", fg="#cdd6f4",
                 font=("Consolas",9,"bold"), padx=8, pady=4,
                 wraplength=420, justify="left").pack()

    def _h(self, e=None):
        if self.tw: self.tw.destroy(); self.tw = None
        self._lc = (None, None)


def _add_btn_tooltip(widget, text):                            ### NEW v0.17.0 ###
    """Attach a simple hover tooltip to any tk.Button widget."""
    _tw = [None]
    def _show(e):
        if _tw[0]: return
        tw = tk.Toplevel(widget); tw.wm_overrideredirect(True)
        tw.configure(bg="#45475a")
        tw.wm_geometry(f"+{e.x_root+16}+{e.y_root+10}")
        tk.Label(tw, text=(text() if callable(text) else text),   ### MODIFIED v0.19.2 B55 — text may be a callable ###
                 bg="#45475a", fg="#cdd6f4",
                 font=("Helvetica", 9), padx=8, pady=4,
                 wraplength=520, justify="left").pack()
        _tw[0] = tw
    def _hide(e=None):
        if _tw[0]: _tw[0].destroy(); _tw[0] = None
    widget.bind("<Enter>", _show)
    widget.bind("<Leave>", _hide)


# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.16.0 — Source ID write helper
# ══════════════════════════════════════════════════════════════════════════════


# ── v0.19.2 B37: every NFO/XML writer reads through _read_for_edit ───────────
_UTF8_BOM = b"\xef\xbb\xbf"


def _xml_text(value):                                          ### NEW v0.19.2 B39 ###
    """A value as NFO/XML element text: & < > escaped.  Values stay unescaped
    in memory (readers use html.unescape / ElementTree), so this runs exactly
    once, at the point of writing."""
    return _xml_escape(str(value))


class NotUtf8Error(ValueError):                                ### NEW v0.19.2 B37 ###
    """The file is not valid UTF-8.  Rewriting it would replace every byte
    that does not decode with U+FFFD ("Am�lie"), so the writer leaves it as it is."""
    def __init__(self, path):
        super().__init__(f"{os.path.basename(path)} is not UTF-8 — not changed "
                         f"(convert it to UTF-8 first)")
        self.path = path


def _read_for_edit(path):                                      ### NEW v0.19.2 B37 ###
    """(text, bom) of an NFO/XML that is about to be changed: strict UTF-8, the
    BOM removed from the text (_atomic_write_text writes it back), newlines
    as a text-mode read gives them.  Raises NotUtf8Error for any other
    encoding, so the file is never written."""
    with open(path, "rb") as f:
        raw = f.read()
    bom = raw.startswith(_UTF8_BOM)
    try:
        text = raw[len(_UTF8_BOM):].decode("utf-8") if bom else raw.decode("utf-8")
    except UnicodeDecodeError:
        raise NotUtf8Error(path) from None
    return text.replace("\r\n", "\n").replace("\r", "\n"), bom


def _read_lines_for_edit(path):                                ### NEW v0.19.2 B37 ###
    """_read_for_edit as a list of lines (like f.readlines())."""
    return io.StringIO(_read_for_edit(path)[0]).readlines()


# ── Atomic NFO/XML writes (v0.19.0) ──────────────────────────────────────────
def _atomic_write_text(path, text, encoding="utf-8"):          ### NEW v0.19.0 ###
    """Write *text* to *path* atomically: temp file in the same folder, flush +
    fsync, then os.replace.  A crash or power loss leaves either the old or
    the new complete file, never a half-written one.  Used by every NFO/XML
    writer (ratings, genres, source IDs, Auto Repair).
    ### MODIFIED v0.19.2 B37 ### a file that starts with a UTF-8 BOM keeps it
    (_read_for_edit returns the text without the BOM)."""
    tmp = f"{path}.mctmp"
    if encoding.lower().replace("_", "-") == "utf-8" and not text.startswith("﻿"):
        try:
            with open(path, "rb") as f:
                if f.read(3) == _UTF8_BOM:
                    encoding = "utf-8-sig"
        except OSError:
            pass
    try:
        with open(tmp, "w", encoding=encoding) as f:
            f.write(text)
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass


_ROOT_CLOSE_RE = re.compile(r"^\s*</([A-Za-z_][\w.:-]*)>\s*$")


def _insert_line_before_root_close(file_lines, new_line, preferred=()):   ### NEW v0.19.0 ###
    """Insert *new_line* before the closing tag of the document root.
    *preferred* names are tried first (e.g. 'Item', 'movie'); otherwise the
    LAST closing tag in the file is used (movie.xml written by Emby/Jellyfin
    uses <Title> as root, v0.18.x appended after </Title> and broke the XML).
    Appends only when no closing tag exists at all."""
    for end in preferred:
        end_re = re.compile(rf"^\s*</{re.escape(end)}>\s*$", re.IGNORECASE)
        for i, line in enumerate(file_lines):
            if end_re.match(line):
                file_lines.insert(i, new_line)
                return file_lines
    for i in range(len(file_lines) - 1, -1, -1):
        if _ROOT_CLOSE_RE.match(file_lines[i]):
            file_lines.insert(i, new_line)
            return file_lines
    file_lines.append(new_line)
    return file_lines


def _write_tag_in_files(nfo_path, xml_path, nfo_tag, xml_tag, value):   ### NEW v0.19.0 ###
    """Set <nfo_tag> in the NFO and/or <xml_tag> in the XML to *value*
    (first occurrence replaced, otherwise inserted before the root's closing
    tag, indentation copied from the file).  Pass None to skip a file.
    Returns (ok, error_str)."""
    errors = []
    value = _xml_text(value)                                    ### NEW v0.19.2 B39 — escaped once, here ###
    for path, tag in ((nfo_path, nfo_tag), (xml_path, xml_tag)):
        if not path or not tag or not os.path.isfile(path):
            continue
        try:
            lines = _read_lines_for_edit(path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            tag_re = re.compile(rf"(<{re.escape(tag)}(?:\s[^>]*)?>)[^<]*(</\s*{re.escape(tag)}\s*>)", re.IGNORECASE)
            found = False
            for i, line in enumerate(lines):
                if tag_re.search(line):
                    lines[i] = tag_re.sub(lambda m: m.group(1) + str(value) + m.group(2), line, count=1)
                    found = True
                    break
            if not found:
                indent = "  "
                for line in lines:
                    m = re.match(r"^([ \t]+)<", line)
                    if m:
                        indent = m.group(1); break
                lines = _insert_line_before_root_close(lines, f"{indent}<{tag}>{value}</{tag}>\n",
                                                       preferred=("movie", "Item", "Title"))
            _atomic_write_text(path, "".join(lines))
        except Exception as e:
            errors.append(f"{os.path.basename(path)}: {e}")
    return (not errors), "; ".join(errors)


def _update_uniqueid_lines(lines, id_type, value):               ### NEW v0.19.1 B19 ###
    """Set every EXISTING Kodi <uniqueid type="imdb"> (id_type "IMDB") or
    <uniqueid type="tmdb"|"themoviedb"> ("TMDB") to *value* — also the
    self-closing form.  Never adds a uniqueid: NFOs that never had them stay
    as they are.  Other attributes (default="true") are kept."""
    types = "imdb" if id_type == "IMDB" else "(?:tmdb|themoviedb)"
    pair = re.compile(rf'(<uniqueid\b[^>]*\btype=["\']?{types}["\']?[^>/]*>)[^<]*(</\s*uniqueid\s*>)', re.IGNORECASE)
    single = re.compile(rf'<uniqueid\b([^>]*\btype=["\']?{types}["\']?[^>]*?)\s*/>', re.IGNORECASE)
    out = []
    for ln in lines:
        ln = pair.sub(lambda m: f"{m.group(1)}{value}{m.group(2)}", ln)
        ln = single.sub(lambda m: f"<uniqueid{m.group(1)}>{value}</uniqueid>", ln)
        out.append(ln)
    return out


def _write_source_id_to_files(nfo_path, xml_path, id_type, chosen_id):  ### FIXED v0.16.0 ###
    """
    Write chosen_id to ALL relevant tags for id_type in both NFO and XML.

    XML IMDB tags:  <IMDB>, <IMDbId>, <IMDB_ID>          (all three written/inserted)
    XML TMDB tags:  <TMDB>, <TMDbId>, <TMDB_ID>          (all three written/inserted)
    NFO IMDB tags:  <imdbid>, <id moviedb="imdb">         (both written/inserted)
    NFO TMDB tags:  <tmdbid>, <id moviedb="tmdb">         (both written/inserted)

    Returns (ok: bool, error_str: str).
    """
    errors = []

    def _detect_indent(file_lines):
        for line in file_lines:
            m = re.match(r'^([ \t]+)<', line)
            if m:
                return m.group(1)
        return "  "

    def _replace_tag_in_lines(file_lines, tag, value):
        """Replace <tag>…</tag> in place. Returns (lines, found)."""
        tag_re = re.compile(rf'(<{re.escape(tag)}[^>]*>)[^<]*(</\s*{re.escape(tag)}\s*>)',
                            re.IGNORECASE)
        for i, line in enumerate(file_lines):
            if tag_re.search(line):
                file_lines[i] = tag_re.sub(rf'\g<1>{value}\2', line)
                return file_lines, True
        return file_lines, False

    def _insert_tag_before_close(file_lines, tag, value, end_tags):
        """Insert <tag>value</tag> before the root's closing tag (end_tags are
        tried first, then the last closing tag in the file).
        ### FIXED v0.19.0 — movie.xml with a <Title> root got the new tag
        appended AFTER </Title>, which made the file invalid ###"""
        indent = _detect_indent(file_lines)
        new_line = f"{indent}<{tag}>{value}</{tag}>\n"
        return _insert_line_before_root_close(file_lines, new_line, preferred=tuple(end_tags))

    def _replace_attr_tag(file_lines, attr_val, value):
        """Replace <id moviedb="attr_val">…</id> in place. Returns (lines, found)."""
        tag_re = re.compile(
            rf'(<id[^>]*moviedb=["\']?{re.escape(attr_val)}["\']?[^>]*>)[^<]*(</\s*id\s*>)',
            re.IGNORECASE)
        for i, line in enumerate(file_lines):
            if tag_re.search(line):
                file_lines[i] = tag_re.sub(rf'\g<1>{value}\2', line)
                return file_lines, True
        return file_lines, False

    # ── Write to XML ──────────────────────────────────────────────────────────
    if xml_path and os.path.isfile(xml_path):
        try:
            lines = _read_lines_for_edit(xml_path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###

            if id_type == "IMDB":
                xml_tags = ["IMDB", "IMDbId", "IMDB_ID"]
            else:
                xml_tags = ["TMDB", "TMDbId", "TMDB_ID"]

            for tag in xml_tags:
                lines, found = _replace_tag_in_lines(lines, tag, chosen_id)
                if not found:
                    lines = _insert_tag_before_close(lines, tag, chosen_id, ["Item"])

            _atomic_write_text(xml_path, "".join(lines))             ### MODIFIED v0.19.0 — atomic ###
        except Exception as e:
            errors.append(f"XML: {e}")

    # ── Write to NFO ──────────────────────────────────────────────────────────
    if nfo_path and os.path.isfile(nfo_path):
        try:
            lines = _read_lines_for_edit(nfo_path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###

            lines = _update_uniqueid_lines(lines, id_type, chosen_id)   ### NEW v0.19.1 B19 ###
            if id_type == "IMDB":
                # Write <imdbid>
                lines, found = _replace_tag_in_lines(lines, "imdbid", chosen_id)
                if not found:
                    lines = _insert_tag_before_close(lines, "imdbid", chosen_id, ["movie"])
                # Write <id moviedb="imdb">
                lines, found = _replace_attr_tag(lines, "imdb", chosen_id)
                if not found:
                    indent = _detect_indent(lines)
                    new_line = f'{indent}<id moviedb="imdb">{chosen_id}</id>\n'
                    lines = _insert_line_before_root_close(lines, new_line, preferred=("movie",))   ### FIXED v0.19.0 ###
                # Write bare <id>ttXXXXXXX</id> (KODI plain IMDB tag)
                # Use [^<]* instead of tt\d+ so corrupt values like
                # "tt33384756/" are fully replaced.  ### FIX v0.17.0-bug1 ###
                bare_id_re = re.compile(r'(<id\s*>)[^<]*(</\s*id\s*>)', re.IGNORECASE)
                bare_found = False
                for i, line in enumerate(lines):
                    if bare_id_re.search(line):
                        lines[i] = bare_id_re.sub(rf'\g<1>{chosen_id}\2', line)
                        bare_found = True
                        break
                if not bare_found:                             ### FIX v0.17.0 — insert if missing ###
                    indent = _detect_indent(lines)
                    bare_line = f"{indent}<id>{chosen_id}</id>\n"
                    lines = _insert_line_before_root_close(lines, bare_line, preferred=("movie",))   ### FIXED v0.19.0 ###
            else:
                # Write <tmdbid>
                lines, found = _replace_tag_in_lines(lines, "tmdbid", chosen_id)
                if not found:
                    lines = _insert_tag_before_close(lines, "tmdbid", chosen_id, ["movie"])
                # Write <id moviedb="tmdb"> or <id moviedb="themoviedb">
                lines, found_t  = _replace_attr_tag(lines, "tmdb", chosen_id)
                lines, found_t2 = _replace_attr_tag(lines, "themoviedb", chosen_id)
                if not found_t and not found_t2:
                    indent   = _detect_indent(lines)
                    new_line = f'{indent}<id moviedb="tmdb">{chosen_id}</id>\n'
                    lines = _insert_line_before_root_close(lines, new_line, preferred=("movie",))   ### FIXED v0.19.0 ###

            _atomic_write_text(nfo_path, "".join(lines))             ### MODIFIED v0.19.0 — atomic ###
        except Exception as e:
            errors.append(f"NFO: {e}")

    if errors:
        return False, "; ".join(errors)
    # ### NEW v0.19.1 B13 ### the other source gets empty placeholder tags when
    # it has no value anywhere, so the user can fill it in by hand.
    return _write_empty_source_tags(nfo_path, xml_path, "TMDB" if id_type == "IMDB" else "IMDB")


_EMPTY_ID_TAGS = {                                             ### NEW v0.19.1 B13 ###
    # (file kind, line to insert, regex that detects an existing tag — any value)
    "IMDB": [("xml", "<IMDB></IMDB>",       r"<IMDB(\s[^>]*)?/?>"),
             ("xml", "<IMDbId></IMDbId>",   r"<IMDbId(\s[^>]*)?/?>"),
             ("xml", "<IMDB_ID></IMDB_ID>", r"<IMDB_ID(\s[^>]*)?/?>"),
             ("nfo", "<imdbid></imdbid>",   r"<imdbid(\s[^>]*)?/?>"),
             ("nfo", '<id moviedb="imdb"></id>', r"""<id\s[^>]*moviedb=["']?imdb["']?"""),
             ("nfo", "<id></id>",           r"<id\s*/?>")],
    "TMDB": [("xml", "<TMDB></TMDB>",       r"<TMDB(\s[^>]*)?/?>"),
             ("xml", "<TMDbId></TMDbId>",   r"<TMDbId(\s[^>]*)?/?>"),
             ("xml", "<TMDB_ID></TMDB_ID>", r"<TMDB_ID(\s[^>]*)?/?>"),
             ("nfo", "<tmdbid></tmdbid>",   r"<tmdbid(\s[^>]*)?/?>"),
             ("nfo", '<id moviedb="tmdb"></id>', r"""<id\s[^>]*moviedb=["']?(?:tmdb|themoviedb)["']?""")],
}


def _write_empty_source_tags(nfo_path, xml_path, id_type):    ### NEW v0.19.1 B13 ###
    """Insert EMPTY tags for id_type ("IMDB"/"TMDB") inside the root of both
    files — placeholders the user can fill in by hand.  Only when that source
    has no value in any tag of either file (a value elsewhere is a "partial"
    ID, which Normalize Sources copies instead).  Existing tags, empty or not,
    are never touched; an unparseable file is left alone; a file is written
    (atomically) only when a tag was added.  Returns (ok, error_str)."""
    src = extract_source_ids_from_files(nfo_path, xml_path)
    if src[f"{id_type.lower()}_all_vals"]:
        return True, ""
    errors = []
    for kind, path, roots in (("xml", xml_path, ("Item",)), ("nfo", nfo_path, ("movie",))):
        if not (path and os.path.isfile(path)) or _parse_root(path) is None:
            continue
        try:
            lines = _read_lines_for_edit(path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            text = "".join(lines)
            indent = next((m.group(1) for m in (re.match(r'^([ \t]+)<', ln) for ln in lines) if m), "  ")
            added = False
            for k, new_tag, rx in _EMPTY_ID_TAGS[id_type]:
                if k != kind or re.search(rx, text, re.IGNORECASE):
                    continue
                lines = _insert_line_before_root_close(lines, f"{indent}{new_tag}\n", preferred=roots)
                added = True
            if added:
                _atomic_write_text(path, "".join(lines))
        except Exception as e:
            errors.append(f"{kind.upper()}: {e}")
    if errors:
        return False, "; ".join(errors)
    return True, ""


def _write_both_source_ids(nfo_path, xml_path, imdb_id, tmdb_id):  ### NEW v0.16.0 ###
    """
    Write both IMDB and TMDB IDs to NFO and XML in one call.
    Backs up files before writing. Returns (ok, error_str).
    Skips whichever ID is None/empty — since v0.19.1 (B13) the missing source
    gets empty placeholder tags (written by _write_source_id_to_files).
    """
    errors = []
    if imdb_id:
        ok, err = _write_source_id_to_files(nfo_path, xml_path, "IMDB", imdb_id)
        if not ok: errors.append(err)
    if tmdb_id:
        ok, err = _write_source_id_to_files(nfo_path, xml_path, "TMDB", tmdb_id)
        if not ok: errors.append(err)
    if errors:
        return False, "; ".join(e for e in errors if e)
    return True, ""

# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.19.1 B15 — hard-coded (burned-in) subtitles, marked by the user
# ══════════════════════════════════════════════════════════════════════════════
# Burned-in subtitles are part of the picture, so FFprobe cannot see them and
# there is no reliable automatic detection (OCR would be slow and often wrong).
# The user marks them; the mark is a standard user tag that Kodi and
# Emby/Jellyfin keep:  NFO <tag>Hardsub POR</tag>,  XML <Tags><Tag>Hardsub POR</Tag></Tags>.
_HARDSUB_RE = re.compile(r"^\s*hardsub\s+([a-z]{3})\s*$", re.IGNORECASE)


def get_hardsub_langs(nfo_path, xml_path):
    """Sorted ISO 639-2 codes marked as hard-coded subtitles in the NFO or XML."""
    codes = set()
    for p, find in ((nfo_path, lambda r: r.findall("tag")),
                    (xml_path, lambda r: (r.find("Tags").findall("Tag") if r.find("Tags") is not None else []))):
        if p and os.path.isfile(p):
            root = _parse_root(p)
            if root is None:
                continue
            for el in find(root):
                m = _HARDSUB_RE.match(el.text or "")
                if m:
                    codes.add(m.group(1).upper())
    return sorted(codes)


def _write_hardsub_tags(nfo_path, xml_path, langs):
    """Make the files hold EXACTLY the Hardsub tags of *langs* (ISO 639-2
    codes): existing 'Hardsub XXX' tags are removed, one tag per language is
    added; every other <tag>/<Tag> is kept.  NFO tags go before </movie>;
    XML tags go into <Tags> (created before the root's end when absent; an
    emptied <Tags> block is removed).  Atomic writes; a file whose result
    would not parse is left untouched.  Returns (ok, error_str)."""
    langs = sorted({(c or "").strip().upper() for c in langs if re.fullmatch(r"[A-Za-z]{3}", (c or "").strip())})
    errors = []

    def _indent_of(lines, default="\t"):
        return next((m.group(1) for m in (re.match(r'^([ \t]+)<', ln) for ln in lines) if m), default)

    def _check_and_write(path, before, after):
        if after == before:
            return
        if _parse_root(path) is not None:            # only guard files that parsed before
            try:
                ET.fromstring(_AMP_FIX_RE.sub("&amp;", after))
            except Exception as ex:
                raise ValueError(f"result would not be valid XML ({ex})")
        _atomic_write_text(path, after)

    if nfo_path and os.path.isfile(nfo_path):
        try:
            text = _read_for_edit(nfo_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            new = re.sub(r"[ \t]*<tag>\s*hardsub\s+[a-z]{3}\s*</tag>[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
            lines = new.splitlines(keepends=True)
            ind = _indent_of(lines)
            for c in langs:
                lines = _insert_line_before_root_close(lines, f"{ind}<tag>Hardsub {c}</tag>\n", preferred=("movie",))
            _check_and_write(nfo_path, text, "".join(lines))
        except Exception as e:
            errors.append(f"NFO: {e}")

    if xml_path and os.path.isfile(xml_path):
        try:
            text = _read_for_edit(xml_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            new = re.sub(r"[ \t]*<Tag>\s*hardsub\s+[a-z]{3}\s*</Tag>[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
            removed = new != text
            lines = new.splitlines(keepends=True)
            ind = _indent_of(lines)
            new_tags = "".join(f"{ind}{ind}<Tag>Hardsub {c}</Tag>\n" for c in langs)
            if langs:
                if re.search(r"<Tags\s*/>", new):
                    new = re.sub(r"<Tags\s*/>", lambda m: "<Tags>\n" + new_tags + f"{ind}</Tags>", new, count=1)
                elif re.search(r"</Tags\s*>", new):
                    m = re.search(r"^([ \t]*)</Tags\s*>", new, re.MULTILINE)
                    if m:                                   # </Tags> on its own line
                        new = new[:m.start()] + new_tags + new[m.start():]
                    else:                                   # one-line <Tags>…</Tags>
                        inline = "".join(f"<Tag>Hardsub {c}</Tag>" for c in langs)
                        new = re.sub(r"</Tags\s*>", lambda mm: inline + "</Tags>", new, count=1)
                else:
                    lines = new.splitlines(keepends=True)
                    lines = _insert_line_before_root_close(lines, f"{ind}<Tags>\n{new_tags}{ind}</Tags>\n",
                                                           preferred=("Item",))
                    new = "".join(lines)
            elif removed:
                new = re.sub(r"[ \t]*<Tags>\s*</Tags>[ \t]*\r?\n?", "", new)
            _check_and_write(xml_path, text, new)
        except Exception as e:
            errors.append(f"XML: {e}")

    if errors:
        return False, "; ".join(errors)
    return True, ""


